(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["ar"] = {"ui":{"lead":"كيف عُثر على الألعاب، ونُسيت، وفُكّت رموزها، وتغيّرت؟ اقرأ {n} حكايات، وأجب عن أسئلة الاختبار في النهاية كلها إجابة صحيحة لتحصل على ختم.","card":"بطاقة الأختام","cardN":"جُمع {n} من {of}","cardAll":"جُمعت كلها!","no":"الحكاية {n}","mins":"{n} د","stamped":"مختومة","back":"كل الحكايات","quiz":"اختبار قصير","links":"شاهد والعب","game":"لعبة","exhibit":"المقتنيات","art":"لوحة","room":"قاعة","room_chance":"الحظ","qn":"السؤال {n} من {of}","right":"صحيح!","wrong":"ليس تمامًا — عُلّمت الإجابة الصحيحة.","got":"تم الختم!","again":"كلها صحيحة!","gotSub":"سُجّل على بطاقة الأختام.","missed":"أخطاء: {n}","retrySub":"أجب عن كل الأسئلة إجابة صحيحة لتحصل على الختم. أعد قراءة الحكاية وحاول مجددًا.","retry":"حاول مجددًا","room_paint":"في الفن","room_map":"الخريطة","kfH":"أهم النقاط","tlH":"خط زمني","refH":"المصادر والقراءات"},"ex":{"ur":"لوحة لعبة أور الملكية","liubo":"لوحة الليوبو وقطعها","pyrgus":"برج النرد الروماني","sugoroku":"لوحة سوغوروكو من شوسوئين","nishapur":"شطرنج نيسابور","lewis":"قطع شطرنج لويس","senet":"صندوق سينيت توت عنخ آمون","ballinderry":"لوحة بالينديري","goose":"لوحة الشطرنج ولعبة الإوزة","kofukuji":"قطع شوغي من كوفوكو-جي","shosoin":"لوحة غو في شوسوئين"},"paint":{"liubo":"شخصان يلعبان الليوبو","sugoroku":"فتاتان تلعبان السوغوروكو","shahnama":"بزرجمهر يكشف سرّ الشطرنج","nefertari":"الملكة نفرتاري تلعب السينيت","chaupar":"شيفا وبارفاتي يلعبان التشوبار","shogi":"زوجان شابان يلعبان الشوغي","hydria":"أخيل وأياكس يلعبان لعبة رقعة (جرّة ماء)","eakins":"لاعبو الشطرنج","weiqi":"طبق عليه خالدون يلعبون الويتشي","webb":"لاعبا الطاولة (خزانة)","liberale":"لاعبو الشطرنج","mirror":"غطاء مرآة: زوجان يلعبان الشطرنج","morris":"لوح لعب (لعبة الطاحونة)","leifeng":"لوح لعبة باغودا لايفنغ","teniers":"دور في النرد (الطاولة)","imari":"طبق عليه رجلان يلعبان الغو","shoei":"الفنون الأربعة"},"ur":{"title":"كيف استعادت لعبة عمرها 4500 عام قواعدها","lead":"جاءت لوحة المقابر الملكية في أور بلا تعليمات. وكان المفتاح في لوح طيني كُتب بعدها بألفي عام.","s":["في عشرينيات القرن العشرين نقّب ليونارد وولي في المقابر الملكية بأور جنوب العراق، فعثر على لوحة من عشرين مربعًا مطعّمة بالصدف واللازورد، تعود إلى نحو 2600–2400 ق.م. وقد ظهرت لوحات مشابهة في أرجاء الشرق الأوسط، فاللعبة لُعبت على نطاق واسع ولزمن طويل.","لكن لم يُعثر معها على ما يشرح طريقة اللعب. لوحة وقطع ونرد — ولا قواعد: مشكلة مألوفة في الألعاب القديمة.","كان المفتاح في مخازن المتحف البريطاني: لوح مسماري نسخه الكاتب البابلي إتي-مردوخ-بلاطو سنة 177/176 ق.م عن لوح يملكه رجل يُدعى إدّن-بيل. وقد كُتب بعد صنع اللوحة بأكثر من ألفي عام.","في مطلع الثمانينيات أدرك إرفينغ فينكل من المتحف البريطاني أن اللوح يصف اللعبة ذاتها ذات العشرين مربعًا. يظهر على ظهره رسم اللوحة مع فأل لكل مربع تقف عليه القطعة. ومن اللوح واللوحة نفسها أعاد فينكل بناء لعبة سباق لاعبَين.","تُلعب إعادة بنائه اليوم في أنحاء العالم. ولا أحد يستطيع الجزم بأن أهل أور لعبوا هكذا تمامًا. ومع ذلك كانت لعبة مشابهة تُلعب في كوتشي جنوب الهند حتى خمسينيات القرن العشرين — دليل على طول عمر هذه اللعبة."],"quiz":[["متى كُتب اللوح الذي كشف القواعد؟","في القرن الثاني ق.م، بعد اللوحة بأكثر من 2000 عام","نحو 2600 ق.م مع اللوحة","في العصور الوسطى (القرن الثاني عشر)","في القرن التاسع عشر"],["من فكّ اللوح وأعاد بناء القواعد؟","إرفينغ فينكل","هوارد كارتر","شامبليون","آرثر إيفانز"],["ماذا يذكر اللوح عن الوقوف على المربعات؟","فألًا بالحظ السعيد أو السيئ","أسماء ملوك","مقادير ضرائب","أسماء نجوم فقط"]],"kf":["تعود الألواح إلى نحو 2600–2400 ق.م، من المقابر الملكية في أور جنوب العراق","أُعيد بناء القواعد من لوح طيني كُتب بعدها بأكثر من ألفي عام","عشرون خانة، وسبع قطع لكل لاعب، ونرد رباعي الأوجه"],"more":[{"h":"مقابر ملكية و«لعبة ملكية»","p":["لم يجد وولي في المقبرة الملكية بأور لوحًا واحدًا بعشرين خانة بل عدة ألواح. وأشهرها، المحفوظ اليوم في المتحف البريطاني، من خشب مطعّم بالصدف والحجر الجيري الأحمر واللازورد، ومنه جاء اسم «لعبة أور الملكية».","لكنها لم تكن لعبة للملوك وحدهم؛ فالألواح نفسها وُجدت من بلاد الرافدين إلى مصر وشرق المتوسط، بل نُقش لوح في أحد القصور الآشورية على قاعدة ثور مجنح برأس إنسان يحرس بوابة، والأرجح أن الحرّاس نقشوه."],"cap":["لعبة أور الملكية في المتحف البريطاني — أدِرها ثلاثية الأبعاد في قاعة المقتنيات"]},{"h":"كيف تعمل اللوحة","p":["تتكوّن الخانات العشرون من كتلة من اثنتي عشرة (3×4) وكتلة من ست (3×2) يصل بينهما «جسر» ضيق من خانتين. وعلى خمس خانات وردة؛ وفي القواعد المعاد بناؤها يمنح الوقوف عليها رمية أخرى ولا يمكن أسر القطعة فيها.","والنرد رباعي الأوجه، عُلّمت رأسان من رؤوسه الأربعة. تُرمى أربعة وتتقدّم القطعة بعدد الرؤوس المعلّمة المتجهة إلى أعلى: من 0 إلى 4. وأكثر النتائج ظهورًا 2 (6 مرات من 16)، أما 0 و4 فمرة واحدة من 16. ويمكنك رميها في قاعة «الحظ» بالمتحف."],"cap":["الخانات العشرون والوردات الخمس. الأرقام الخضراء طريق لاعب واحد خانةً خانة (القواعد المعاد بناؤها)","كيف تسقط أربعة أحجار نرد رباعية الأوجه (من 16 حالة متساوية الاحتمال)"]},{"h":"ماذا يقول اللوح","p":["يشرح وجه اللوح اللعبة، ويرسم ظهره اللوحة وفي خاناتها علامات الأبراج. والعبارات الخاصة بكل خانة تشبه الطوالع — «ستلقى صديقًا»، «ستشرب جعة طيبة» — فقد كانت اللعبة مرتبطة بالحظ.","غير أن جزءًا من اللوح مكسور، فلا تُقرأ القواعد كلها. وقد بنى فينكل من السطور المقروءة وشكل اللوحة أكثر لعبة تماسكًا، واقترح باحثون آخرون صيغًا أخرى."]},{"h":"آخر اللاعبين في الهند","p":["وعرف فينكل لاحقًا أن الجماعة اليهودية في كوتشي (كوشين) جنوب الهند ظلت حتى وقت قريب تلعب لعبة بعشرين خانة على لوحة شكلها قريب جدًا.","وتوارثتها البيوت حتى هاجرت الجماعة إلى إسرائيل في خمسينيات القرن العشرين. ولعل اللعبة بلغت الهند عبر طرق التجارة القديمة وعاشت أكثر من أربعة آلاف عام."]}],"tl":[["نحو 2600–2400 ق.م","توضع ألواح العشرين خانة في المقابر الملكية بأور"],["القرن الثامن ق.م","يُنقش لوح على قاعدة حارس بوابة في قصر آشوري"],["177/176 ق.م","ينسخ كاتب بابلي لوح القواعد"],["1922–1934","ينقّب وولي في أور ويجد الألواح"],["أوائل الثمانينيات","يقرأ فينكل اللوح ويعيد بناء القواعد"],["حتى الخمسينيات","تُلعب لعبة قريبة جدًا في كوتشي جنوب الهند"]]},"liubo":{"title":"لماذا اختفت لعبة الليوبو؟","lead":"في عهد الهان لعبها الجميع من الإمبراطور إلى عامة الناس. وفي بضعة قرون نُسيت حتى قواعدها.","s":["كانت الليوبو الشغف الكبير في صين أسرة هان (206 ق.م – 220 م). تظهر في تماثيل المقابر والنقوش الحجرية وحتى في زخارف المرايا، وكثيرًا ما يُصوَّر الخالدون وهم يلعبونها.","بعد سقوط الهان تراجعت الليوبو سريعًا، ويبدو أن قواعدها كانت قد ضاعت بحلول عهد تانغ. السبب غير واضح؛ ومن الآراء أن اللاعبين انصرفوا إلى ألعاب أخرى مثل الويتشي (غو).","بقيت اللوحات والأدوات. تحمل اللوحات نقشًا مميزًا من أشكال T وL وV، والأرجح أن الحركات كانت تُحدَّد برمي عيدان رفيعة. والنقش نفسه يزيّن ما يُعرف بمرايا TLV.","وتتجمع الأدلة المكتوبة أيضًا شيئًا فشيئًا. ففي عام 1993 عُثر في مقبرة من عهد الهان في يينوان (جيانغسو) على نص للعرافة يستخدم مخطط اللوحة. ومن مقبرة ليو خه، مركيز هايهون، التي نُقّب فيها في العقد الثاني من القرن الحادي والعشرين، خرج أكثر من ألف شريحة خيزران عن الليوبو، ولا تزال قيد الدراسة.","الليوبو في الأطلس إعادة بناء تقوم على هذه الأدلة. يعيد الباحثون بناءها بطرق مختلفة قليلًا، ولم تُعرف القواعد الحقيقية كاملة بعد — وقد تغيّر الاكتشافات الجديدة طريقة لعبها."],"quiz":[["في عهد أي أسرة كانت الليوبو شائعة جدًا؟","هان","مينغ","تشينغ","سونغ"],["أين عُثر على أكثر من ألف شريحة خيزران عن الليوبو؟","في مقبرة ليو خه، مركيز هايهون","في ضريح الإمبراطور الأول","في كهوف دونهوانغ","في المدينة المحرمة"],["ما الذي كان يُرمى غالبًا لتحديد الحركة في الليوبو؟","عيدان رفيعة","نرد بعشرين وجهًا","خذروف","بطاقات مصوّرة"]],"kf":["كانت شائعة جدًا في الصين من عصر الممالك المتحاربة إلى أسرة هان (القرن الخامس ق.م – القرن الثالث م)","لوحة بخطوط على هيئة T وL وV، وتُرمى عيدان رفيعة لتحديد الحركة","اندثرت سريعًا بعد سقوط هان، وما زالت قواعدها غير معروفة كلها"],"more":[{"h":"لوحة TLV","p":["لوحة ليوبو مربعة، في وسطها مربع، وفي منتصف كل ضلع T، وحولها أشكال L، وفي الأركان V. ويُعتقد أن القطع كانت تسير على هذه الخطوط وبينها.","وتظهر الخطوط نفسها على ظهور المرايا («مرايا TLV») وعلى المزاول الشمسية. ويرى بعض الباحثين في اللوحة خريطة للكون — السماء والأرض والجهات الأربع — مما يوحي بأن ليوبو كانت أكثر من تسلية."],"cap":["خطوط لوحة ليوبو (نمط TLV): مربع في الوسط، وحرف T على كل ضلع، وأشكال L وV نحو الأركان"]},{"h":"كيف كانت تُلعب","p":["يرى أكثر الباحثين أن لكل لاعب ست قطع، وأنهم كانوا يرمون عيدانًا رفيعة من الخيزران لتحديد الحركة. ويُقال إن «الست» (ليو) في الاسم من هذه العيدان الستة أو القطع الستة.","ويبدو أن القطعة المتقدمة كانت تصير «بومة» (شياو) قوية. وفي قصيدة من نحو القرن الثالث ق.م، «استدعاء الروح» من «أغاني تشو»، بيت يقول: «إذا صارت بومة اندفعوا وصاحوا: خمسة بيض!». وتصف النصوص أيضًا طريقة لعب تُصاد فيها «الأسماك» من «الماء» في وسط اللوحة."],"cap":["تمثالان للاعبَي ليوبو صُنعا لقبر من عهد هان (متحف المتروبوليتان للفنون)"]},{"h":"أطقم من القبور","p":["ضمّ القبر رقم 3 في ماوانغدوي بتشانغشا في هونان (نحو 168 ق.م) طقمًا كاملًا — اللوحة والقطع والعيدان — في صندوق مطلي باللك، ليلعب الميت في العالم الآخر.","وكثيرًا ما تُظهر النقوش البارزة على جدران القبور الخالدين يلعبون ليوبو على قمم الجبال. فقد ارتبطت اللعبة بعالم الخلود وطول العمر."],"cap":["لوحة ليوبو في مقتنيات المتحف — شاهدها ثلاثية الأبعاد في قاعة المقتنيات"]}],"tl":[["القرن 5–3 ق.م (الممالك المتحاربة)","تبدأ ألواح ليوبو بالوضع في القبور"],["نحو القرن 3 ق.م","«استدعاء الروح» يصف دورًا من ليوبو"],["نحو 168 ق.م","يوضع طقم كامل في القبر رقم 3 بماوانغدوي"],["206 ق.م – 220 م (هان)","يلعبها الأباطرة والعامة؛ وتظهر على النقوش والمرايا"],["تانغ (القرن 7–10)","يُعتقد أن القواعد كانت قد نُسيت"],["1993","يظهر من قبور يينوان الهانية نص عرافة يستعمل اللوحة"],["العقد الثاني من القرن 21","تُكتشف شرائح خيزران عن ليوبو في قبر مركيز هايهون ليو خه"]]},"zeno":{"title":"رمية الإمبراطور زينون المشؤومة","lead":"قبل ألف وخمسمئة عام رمى إمبراطور النرد — وبقيت النتيجة في قصيدة حتى اليوم.","s":["أحبّ الرومان لعبة التابولا، وهي سباق بالنرد على لوحة من 24 نقطة: جدّة الطاولة (النرد). ولمنع الرميات المغشوشة استعملوا حتى أبراج النرد التي يتدحرج النرد داخلها.","نحو سنة 480 كان الإمبراطور الروماني الشرقي زينون يلعب التابولا. أظهرت نرداته الثلاث 2 و5 و6. لم يكن أمامه إلا أن يتحرك كما تفرض القواعد، فبقيت على لوحته ثماني قطع منفردة بلا حماية.","سجّل الدَّور أغاثياس، المؤرخ والشاعر في القرن السادس الذي عاش بعد زينون ببضعة عقود. وقصيدته القصيرة (إبيغرام) تذكر مواضع القطع — سجلّ نادر لمباراة قديمة.","في القرن التاسع عشر استخلص العالم الفرنسي بيك دو فوكيير من القصيدة الوضع والقواعد: خمس عشرة قطعة لكل لاعب وثلاثة أحجار نرد. تبدأ القطع كلها خارج اللوحة، ويتحرك اللاعبان في الاتجاه نفسه.","مقارنة بالطاولة اليوم، استخدمت التابولا ثلاثة أحجار نرد، وبدأت بلا قطع على اللوحة، ولم يكن فيها مكعب المضاعفة. وبفضل سوء حظ إمبراطور نعرف كيف كانت التابولا."],"quiz":[["ماذا أظهر نرد زينون؟","2 و5 و6","6 و6 و6","1 و1 و1","3 و4 و5"],["من سجّل الدَّور في قصيدة؟","أغاثياس","هوميروس","بلينيوس","شيشرون"],["ما أحد الفروق بين التابولا والطاولة اليوم؟","التابولا استخدمت ثلاثة أحجار نرد","ثلاثون قطعة لكل لاعب","لوحة من 12 نقطة","القطع تتحرك إلى الخلف"]],"kf":["كانت التابولا تُلعب على 24 نقطة بثلاثة أحجار نرد — وهي سلف الطاولة","بقي دور الإمبراطور زينون نحو سنة 480 بوضعه كاملًا في قصيدة","بل صنع الرومان «أبراج نرد» لمنع الغش"],"more":[{"h":"لوحة التابولا","p":["لوحة التابولا، مثل لوحة الطاولة اليوم، 24 نقطة في صفّين من 12. ولكل لاعب خمس عشرة قطعة تكون كلها خارج اللوحة في البداية، فتدخل بحسب ثلاثة أحجار نرد وتدور ثم تخرج.","والفرق الكبير عن الطاولة أن اللاعبين يسيران في الاتجاه نفسه. وكانت القطعة الوحيدة في نقطتها تُضرب إذا حلّ الخصم عليها، فتعود لتدخل من جديد. وقطع زينون الثماني كانت من هذا النوع المكشوف."],"cap":["لوحة تابولا: 24 نقطة في صفّين من 12، وقطع اللاعبين كليهما تسير في الاتجاه نفسه (السهم)"]},{"h":"أداة ضد الغش","p":["كان الرومان مولعين بالنرد. وقد حظر القانون القمار، ويُقال إنه لم يُبَح إلا في عيد ساتورناليا الشتوي — لكن الرهان لم يتوقف، ولا خفة اليد في رمي النرد.","ومن هنا برج النرد: تُلقى الأحجار من أعلاه فتصطدم بألواح في داخله وتتدحرج خارجة من أسفله. وعلى برج من القرن الرابع وُجد في فيلا بألمانيا نقش مخرّم: «هُزم البيكت وأُبيد العدو — العبوا آمنين»."],"cap":["برج النرد من فيتفايس-فرويتسهايم (القرن الرابع) — شاهده ثلاثي الأبعاد في قاعة المقتنيات"]},{"h":"الأباطرة والنرد","p":["لم يكن زينون وحده. فبحسب المؤرخ سويتونيوس كان الإمبراطور كلوديوس في القرن الأول مغرمًا بالنرد حتى ألّف كتابًا في فنّه، وجهّز عربته كي لا تنزلق اللوحة وهو يلعب.","وتكشف المواقع الرومانية أيضًا ألواحًا كثيرة من 36 حرفًا في كلمات من ستة أحرف؛ يقوم كل حرف مقام خانة، وعلى بعضها سخرية مثل: «قم، لا تعرف اللعب؛ أفسح المكان للاعب»."],"cap":["كانت الطاولات والنرد متعة من الأباطرة إلى الجنود (ارمِ النرد المكعب في قاعة الحظ)"]}],"tl":[["القرن الأول","الإمبراطور كلوديوس يكتب كتابًا عن لعب النرد"],["القرن الرابع","يُستعمل برج نرد في فيلا بألمانيا"],["نحو 480","دور الإمبراطور زينون السيئ الحظ"],["القرن السادس","أغاثياس ينظم الدور شعرًا"],["نحو القرن العاشر","تدخل القصيدة «المختارات اليونانية»"],["1869","بيك دو فوكيير يحلّ الوضع والقواعد"],["1934","ر. ج. أوستن يعيد فحص دور زينون بالتفصيل"]]},"sugoroku":{"title":"السوغوروكو المحظورة","lead":"حظرها الحكّام، وواصل الناس اللعب. حكاية سوغوروكو اللوحة في اليابان من العصور القديمة إلى عصر إيدو.","s":["تحفظ خزانة شوسوئين لوحة سوغوروكو يُروى أنها كانت من محبوبات الإمبراطور شومو. وليست هذه سوغوروكو الورقية المصوّرة، بل «بان-سوغوروكو» التي تُحرَّك فيها قطع بيضاء وسوداء على لوحة — قريبة الطاولة.","ارتبطت السوغوروكو بالقمار مبكرًا. ووفقًا لكتاب «نيهون شوكي» حظرتها الإمبراطورة جيتو سنة 689.","كما منعت مدوّنة يورو، المعمول بها منذ 757، الرهبان والراهبات من لعبها. وتكرر الحظر مرة بعد مرة، ما يدل على أنه لم يُحترم.","في عصر هييان بقيت اللعبة رائجة، وتظهر في «كتاب الوسادة» و«حكاية غينجي». وتروي «حكاية هيكي» أن الإمبراطور المعتزل شيراكاوا عدّ ثلاثة أشياء لا يقدر عليها: مياه نهر كامو، ونرد السوغوروكو، والرهبان المحاربين في جبل هيئي.","ما زالت مطبوعات عصر إيدو تُظهر فتيات يلعبن بان-سوغوروكو في البيت. لكن بحلول عصر ميجي كادت لعبة اللوحة تختفي، وصارت كلمة «سوغوروكو» تعني اللعبة الورقية المصوّرة."],"quiz":[["بان-سوغوروكو، مثل لوحة شوسوئين، قريبة أي لعبة؟","الطاولة (النرد)","الشوغي","الغو","ورق اللعب"],["وفقًا لـ«نيهون شوكي»، من حظر السوغوروكو سنة 689؟","الإمبراطورة جيتو","الإمبراطور شومو","الإمبراطور كانمو","الإمبراطور ميجي"],["لم يقدر شيراكاوا على نهر كامو والرهبان المحاربين و… ماذا؟","نرد السوغوروكو","قطع الشوغي","أحجار الغو","كرة الكيماري"]],"kf":["بان-سوغوروكو قريبة الطاولة، وكانت تُلعب في اليابان في القرن السابع","حُظرت مرارًا بسبب القمار، أولها على يد الإمبراطورة جيتو سنة 689","في عصر ميجي كادت تُنسى، وصار «سوغوروكو» اسمًا للعبة الصور الورقية"],"more":[{"h":"لوحة شوسوين","p":["لوحة شوسوين من خشب الورد، مطعّمة بدقة بالعاج والأخشاب المصبوغة، وفيها 24 خانة، اثنتا عشرة في كل جانب، وزهور على الفاصل الأوسط.","ويحفظ شوسوين أيضًا كثيرًا من قطع السوغوروكو المصنوعة من الزجاج والحجر. وتُلعب بان-سوغوروكو بخمس عشرة قطعة بيضاء وخمس عشرة سوداء وحجري نرد، وهي عدة قريبة جدًا من الطاولة. ويُرجّح أنها جاءت من النرد الفارسي عبر الصين."],"cap":["لوحة سوغوروكو في شوسوين من خشب الورد المطعّم — العب عليها في قاعة المقتنيات"]},{"h":"طريقة اللعب","p":["يرتّب كل لاعب خمس عشرة قطعة بترتيب ثابت ويتقدّم بحسب حجري النرد. ويدور الأبيض والأسود في اتجاهين متعاكسين، ويفوز من يجمع أولًا كل قطعه في الخانات الست الأخيرة.","والقطعة الوحيدة في خانتها قد تُضرب وتعود إلى البداية. ولا يدخل الخصم خانة فيها قطعتان أو أكثر، فالبراعة في بناء الحواجز. وفي قاعة المقتنيات يمكنك اللعب هكذا على لوحة شوسوين."],"cap":["لوحة بان-سوغوروكو (مخطط): الخانات الـ24، والأبيض والأسود يسيران في اتجاهين متعاكسين"]},{"h":"حظر وموضة","p":["بعد جيتو حُظرت سوغوروكو مرات كثيرة أخرى، إذ لم يكفّ الناس عن خسارة ثرواتهم في القمار. وأصدرت شوغونية كاماكورا أيضًا قوانين ضد الرهان عليها.","لكنها كانت كذلك من مهارات النبلاء؛ فكانت اللوحة الجميلة جزءًا من جهاز العروس، وصُنعت في عصر إيدو ألواح فاخرة مطلية باللك. مكروهة أداةً للقمار ومحبوبة كنزًا — كان لبان-سوغوروكو الوجهان معًا."],"cap":["بان-سوغوروكو في لوحة من عصر إيدو (قاعة الألعاب في الرسوم)"]}],"tl":[["القرن السابع","تصل بان-سوغوروكو من الصين"],["689","الإمبراطورة جيتو تحظر السوغوروكو (نيهون شوكي)"],["القرن الثامن","تدخل اللوحة المطعّمة شوسوين"],["757","قانون يورو يمنعها على الرهبان والراهبات"],["عصر هييان","تظهر في «كتاب الوسادة» و«حكاية غينجي»"],["القرن الثاني عشر","شكوى شيراكاوا من «نرد السوغوروكو» (حكاية هيكي)"],["عصر إيدو","تُصنع ألواح فاخرة لجهاز العرائس"],["عصر ميجي","تكاد بان-سوغوروكو تختفي"]]},"queen":{"title":"كيف صار الوزير أقوى قطع الشطرنج","lead":"كانت أقوى قطعة اليوم في الأصل مستشارًا لا يتحرك إلا مربعًا واحدًا قطريًا.","s":["انتقل الشطرنج من الهند إلى فارس ثم إلى العالم العربي. وفي ملحمة «الشاهنامه» الفارسية يحلّ الحكيم بزرجمهر لغز الشطرنج المرسَل من الهند. وعلى تلك الرقع كانت القطعة المجاورة للملك هي «الفرزان» أو «الفرز»، أي المستشار.","كان الفرز يتحرك مربعًا واحدًا قطريًا فقط — قطعة ضعيفة جدًا. وفي طقم شطرنج نيسابور (إيران) من القرن الثاني عشر يبدو عرشًا صغيرًا أصغر من عرش الملك.","حين بلغ الشطرنج أوروبا صار المستشار ملكة؛ وبين قطع لويس من القرن الثاني عشر ملكات. لكن الاسم الجديد لم يغيّر الحركة: بقيت ضعيفة.","جاء التحول الكبير في إسبانيا أواخر القرن الخامس عشر. فقصيدة Scachs d’amor («شطرنج الحب») المكتوبة في بلنسية نحو 1475 تُعدّ أقدم سجلّ للوزير الحديث الذي يتحرك أي مسافة في الصفوف والأعمدة والأقطار. ثم نشرت كتب لوسينا (1497) وداميانو (1512) القاعدة الجديدة في أوروبا.","لا يُعرف يقينًا لماذا صار الوزير بهذه القوة. يرى بعضهم أن الناس أرادوا مباريات أسرع، ويشير آخرون إلى تأثير ملكات قويات مثل إيزابيلا الأولى. وفي كل الأحوال قرّب هذا التغيير الشطرنج كثيرًا من لعبة اليوم."],"quiz":[["في الشطرنج الفارسي والعربي، أي قطعة كانت في مكان الوزير اليوم؟","الفرز (المستشار)","الفيل","الرخّ","الفرس"],["كيف كان الفرز الأصلي يتحرك؟","مربعًا واحدًا قطريًا","أي مسافة في خط مستقيم","يقفز مربعين","لا يتحرك"],["أين كُتبت القصيدة التي تضم أقدم سجلّ للوزير الحديث؟","بلنسية، القرن الخامس عشر","الهند، القرن السادس","لويس، القرن الثاني عشر","لندن، القرن التاسع عشر"]],"kf":["بدأ الوزير/الملكة «فرزًا» فارسيًا عربيًا (مستشارًا) لا يتحرك إلا خانة واحدة قطريًا","ظهرت الملكة القوية الحديثة مكتوبة لأول مرة في إسبانيا نحو 1475","نشرت الكتب المطبوعة القواعد الجديدة في أوروبا خلال عقود قليلة"],"more":[{"h":"المستشار الضعيف","p":["لم يكن الفرز يتحرك إلا خانة واحدة قطريًا — بعيدًا جدًا عن ملكة اليوم التي تعبر الرقعة من طرف إلى طرف. وكان الشطرنج آنذاك بطيئًا، وقد يستغرق الدور ساعات.","وكان الفيل لا يقفز إلا إلى الخانة الثانية قطريًا. والبيدق الذي يبلغ الصف الأخير يترقّى — لكن إلى هذا الفرز الضعيف وحده."],"cap":["مدى حركة الفرز (يسارًا) والملكة الحديثة (يمينًا)"]},{"h":"«شطرنج الملكة» و«الشطرنج المجنون»","p":["لما ظهرت الملكة الجديدة سُمّيت اللعبة في إسبانيا «شطرنج الملكة»، وفي إيطاليا لشدتها «الشطرنج المجنون» (scacchi alla rabbiosa). وفي الفترة نفسها صار الفيل ينزلق قطريًا أي مسافة.","ومع القطع الأقوى صارت اللعبة سريعة شرسة. وظهرت كتب عن فخاخ تُكسب في نقلات قليلة وعن افتتاحيات ثابتة، فصار الشطرنج لعبة تُدرَس."],"cap":["ليبيرالي دا فيرونا، «لاعبو الشطرنج» (نحو 1475)، رُسمت حين وُلدت الملكة الجديدة تمامًا"]},{"h":"لماذا ملكة؟","p":["لا يُعرف يقينًا لماذا صار المستشار ملكة. ولعل رؤية القطعة التي بجوار الملك زوجةً له بدت طبيعية. ففي اللاتينية صار «فرز» «فيرسيا»، ثم سُمّيت القطعة «ريجينا» أي الملكة.","ويُختلف أيضًا في سبب قوتها: لتسريع اللعب، أو لأنه كان عصر ملكات قويات مثل إيزابيلا الأولى ملكة قشتالة. وقد ربطت المؤرخة مارلين يالوم هذا التغير بمكانة المرأة في العصور الوسطى."],"cap":["الملكة من قطع شطرنج جزيرة لويس (القرن الثاني عشر)، ما زالت بحركتها القديمة الضعيفة"]}],"tl":[["نحو القرن السادس","تنشأ التشاتورانغا في الهند، سلف الشطرنج"],["القرن 7–9","تُلعب في فارس والعالم العربي، والفرز بجوار الملك"],["نحو القرن العاشر","يصل الشطرنج إلى أوروبا"],["القرن الثاني عشر","بين قطع لويس ملكات (ما زالت ضعيفة)"],["نحو 1475","القصيدة البلنسية «سكاكس دامور» تذكر الحركة الجديدة"],["1497","يُطبع كتاب لوثينا في الشطرنج بإسبانيا"],["1512","يصدر كتاب داميانو في إيطاليا فتنتشر القواعد"]]},"senet":{"title":"كيف صارت السينيت رحلة إلى العالم الآخر","lead":"لعبة لُعبت في مصر نحو ثلاثة آلاف عام صارت رمزًا لرحلة الروح بعد الموت.","s":["السينيت لعبة مصرية قديمة تتقدم فيها القطع على لوحة من ثلاثة صفوف في كل منها عشرة مربعات. وُجدت في مقابر الأسرة الأولى، نحو 3100 ق.م، شظايا قد تكون من لوحات سينيت. لعب الملوك على صناديق فاخرة، وعامة الناس على لوحات محفورة في الحجر.","معنى اسمها «العبور». ومنذ الدولة الحديثة (نحو 1550 ق.م) ارتبطت السينيت برحلة روح المتوفى عبر العالم الآخر.","يصوّر الفصل السابع عشر من «كتاب الموتى» المتوفى يلعب السينيت أمام خصم غير مرئي. وعلى جدار مقبرة نفرتاري، زوجة رمسيس الثاني، تجلس الملكة أمام لوحة سينيت.","ضمّت مقبرة توت عنخ آمون خمسة صناديق ألعاب على الأقل. أحدها صندوق كبير من الأبنوس والعاج، يحمل السينيت في أعلاه ولعبة أخرى من عشرين مربعًا على وجهه الآخر.","ومع ذلك لم يُعثر على نص يشرح القواعد كاملة. وفي القرن العشرين أعاد جيكييه وبيل وكيندال (1978) وغيرهم بناء طريقة للعب، كلٌّ على طريقته، من اللوحات والصور وشذرات النصوص. والسينيت في الأطلس واحدة من هذه الطرق القائمة على البحث."],"quiz":[["ما معنى اسم «السينيت»؟","العبور","لعبة الملك","ثلاثون بيتًا","عبور النهر"],["بماذا ارتبطت السينيت في الدولة الحديثة؟","برحلة الروح عبر العالم الآخر","بطقوس الاستسقاء","بخطط الحرب","بالتنبؤ بالحصاد"],["كم صندوق ألعاب على الأقل ضمّت مقبرة توت عنخ آمون؟","خمسة","واحد","اثنان","مئة"]],"kf":["من أقدم ألعاب اللوحة في العالم: تتسابق القطع على لوحة من 3 × 10 خانات","اسمها يعني «العبور»، وفي الدولة الحديثة صارت رحلة الروح عبر العالم الآخر","لم تبقَ قواعدها؛ وطرق اللعب الحالية إعادة بناء من القرن العشرين"],"more":[{"h":"ثلاثون خانة وخانات خاصة","p":["لوحة السينيت ثلاثة صفوف من عشر خانات، أي ثلاثون خانة. ويُعتقد أن القطع كانت تسير في الصف الأول من اليسار إلى اليمين، وفي الثاني من اليمين إلى اليسار، ثم في الثالث من اليسار إلى اليمين، فترسم حرف S.","وكثيرًا ما رُسمت على الخانات الخمس الأخيرة علامات خاصة؛ فالخانة 26 «البيت الجميل»، و27 «الماء»، وفي أغلب إعادات البناء تعود القطعة التي تسقط في الماء. وعلى الخانات 28–30 أرقام أو آلهة العالم الآخر."],"cap":["لوحة سينيت. تسير القطع على هيئة S، وعلى الخانات الخمس الأخيرة (26–30) علامات خاصة"]},{"h":"التقدّم بعصيّ الرمي","p":["بدل النرد كانت تُرمى أربع عصيّ مسطحة من جهة ومستديرة من الأخرى، أو عظام كعاب الحيوانات. ويرى كثير من الباحثين أن القطعة تتقدّم بعدد الوجوه المسطحة المتجهة إلى أعلى، وأن انعدامها يُحسب خمسة.","وهذا العدّ هو نفسه تمامًا في عصيّ اليوت في كوريا البعيدة. ارمِ العصيّ في قاعة الحظ بالمتحف وانظر كم تظهر بعض الأرقام أكثر من غيرها."],"cap":["عصيّ الرمي المصرية (ارمها في قاعة الحظ)"]},{"h":"صناديق ألعاب توت عنخ آمون","p":["ضمّ قبر توت عنخ آمون، الذي فتحه هوارد كارتر سنة 1922، خمسة صناديق ألعاب على الأقل. أكبرها من الأبنوس والعاج، وله درج للقطع والعصيّ.","وكانت الصناديق ذات اللوحتين على الوجهين شائعة آنذاك: سينيت على وجه، وعلى الآخر لعبة العشرين خانة نفسها التي في لعبة أور الملكية. أُريد للملك أن يلعب الاثنتين في العالم الآخر."],"cap":["صندوق سينيت توت عنخ آمون — شاهده ثلاثي الأبعاد والعب عليه في قاعة المقتنيات"]}],"tl":[["نحو 3100 ق.م","شظايا لوحة شبيهة بالسينيت في قبر من الأسرة الأولى"],["نحو 2600 ق.م","رسوم قبور الدولة القديمة تُظهر اللاعبين"],["منذ نحو 1550 ق.م","الدولة الحديثة: ترتبط السينيت برحلة العالم الآخر"],["نحو 1323 ق.م","خمسة صناديق ألعاب في قبر توت عنخ آمون"],["نحو 1250 ق.م","تُرسم نفرتاري أمام لوحة سينيت"],["1922","كارتر يفتح قبر توت عنخ آمون"],["1978","كيندال ينشر إعادة بناء للقواعد"]]},"lewis":{"title":"قطع الشطرنج الخارجة من الرمال","lead":"قطع من العصور الوسطى وُجدت في جزيرة اسكتلندية سنة 1831 — وقطعة أخرى من الورشة نفسها ظهرت في درج بعد 188 عامًا.","s":["في سنة 1831 عُثر في جزيرة لويس شمال غرب اسكتلندا على كنز من القطع المنحوتة غالبًا من ناب الفظ: 78 قطعة شطرنج و14 قرصًا لألعاب اللوحة وإبزيم، أي 93 قطعة في المجموع.","لا يُعرف بدقة أين ولا كيف وُجدت. يُذكر غالبًا خليج أويغ على الساحل الغربي، لكن ثمة أماكن أخرى مقترحة. ولا يُعرف من دفنها هناك ولا لماذا.","يُعتقد أنها صُنعت أواخر القرن الثاني عشر في منطقة تروندهايم بالنرويج: ملوك، وملكات شاردات الذهن، وأساقفة، وفرسان على خيول صغيرة ممتلئة، وحرّاس يعضّون حافة دروعهم — ولعلهم محاربو «البيرسيركر» في الملاحم الإسكندنافية.","توجد اليوم 82 قطعة في المتحف البريطاني و11 في المتحف الوطني الاسكتلندي. وطالما قيل إن بعض القطع ناقصة لإكمال الأطقم.","في سنة 2019 تبيّن أن حارسًا اشتراه تاجر تحف من إدنبرة سنة 1964 بخمسة جنيهات فقط، واحتفظت به عائلته في درج، من صنع ورشة قطع لويس. وبيع في مزاد سوذبيز بمبلغ 735 ألف جنيه."],"quiz":[["في أي سنة وُجدت القطع في لويس؟","1831","1066","1931","1700"],["مِمّ صُنعت القطع غالبًا؟","من ناب الفظ","من الرخام","من الذهب","من الزجاج"],["في أي سنة اشتُري الحارس الذي بيع سنة 2019 بخمسة جنيهات؟","1964","1831","1990","2018"]],"kf":["93 قطعة وقرصًا عُثر عليها في جزيرة لويس باسكتلندا سنة 1831","نُحتت غالبًا من ناب الفظ في النرويج أواخر القرن الثاني عشر","وهي اليوم موزعة بين المتحف البريطاني والمتاحف الوطنية في اسكتلندا"],"more":[{"h":"قطع الشطرنج الـ78","p":["القطع الـ78 هي 8 ملوك و8 ملكات و16 أسقفًا و15 فارسًا و12 حارسًا و19 بيدقًا — أجزاء من أربعة أطقم على الأقل.","يلبس الأساقفة التاج الأسقفي. وتحوّل «الفيل» في الشطرنج إلى أسقف حدث في أوروبا، وقطع لويس من أقدم أمثلته. وبعض الحراس يعضّون دروعهم، ويُعتقد أنهم يمثلون «البيرسركر»، المحاربين الذين يقاتلون في هياج."],"cap":["قطع شطرنج لويس (شاهدها ثلاثية الأبعاد في قاعة المقتنيات)","قطع الشطرنج الـ78 بحسب النوع"]},{"h":"ناب الفظ وبحار الشمال","p":["أغلب القطع من ناب الفظ وبعضها من سن الحوت. وكان ناب الفظ كنزًا من كنوز بحار الشمال يُجلب من غرينلاند وشمال النرويج.","وكانت لويس آنذاك من جزر ملك النرويج، وانتقلت إلى اسكتلندا بمعاهدة بيرث سنة 1266. وقد وُجدت قرب كاتدرائية تروندهايم شظايا منحوتة بالطريقة نفسها، وهي دليل على موطن صنعها."],"cap":[]},{"h":"أسطورة الاكتشاف وشهرتها اليوم","p":["تُروى حكايات كثيرة: بقرة نبشتها من الرمل، أو أحد السكان ويُدعى مالكوم ماكلاود. وباعها مكتشفها سريعًا، واشترى المتحف البريطاني أكثرها عن طريق إدنبرة.","وبوجوهها العابسة الطريفة صارت شديدة الشعبية، وتُباع نسخها في أنحاء العالم. واستُخدمت في شطرنج السحرة بفيلم «هاري بوتر وحجر الفيلسوف» (2001) قطع مستوحاة منها."],"cap":[]}],"tl":[["أواخر القرن الثاني عشر","تُصنع القطع في النرويج (قرب تروندهايم)"],["1266","معاهدة بيرث تمنح الجزر، ومنها لويس، لاسكتلندا"],["1831","يُعثر على القطع الـ93 معًا في لويس"],["1831–32","المتحف البريطاني يشتري 82"],["1888","المتحف الوطني الاسكتلندي يقتني 11"],["2001","تظهر في شطرنج السحرة في «هاري بوتر»"],["2019","حارس اشتُري بخمسة جنيهات يُباع بـ735 ألفًا"]]},"tafl":{"title":"فرار الملك وترجمة خاطئة","lead":"استُخلصت قواعد لعبة الفايكنغ من مذكرات رحلة إلى لابلاند في القرن الثامن عشر.","s":["في شمال أوروبا زمن الفايكنغ كانت تُلعب ألعاب لوحة تُسمى «تافل». ملك في الوسط مع قلة من المدافعين يواجهون جيشًا أكبر يحاصرهم — لعبة بين طرفين غير متكافئين.","لوحة خشبية من القرن العاشر عُثر عليها في بالينديري بإيرلندا سنة 1932 فيها 7×7 ثقوب، وقد عُلِّم الثقب الأوسط والزوايا الأربع — ولعلها مكان الملك وملاجئه.","لكن لم يبقَ تقريبًا أي وصف للقواعد من العصور الوسطى. ومن أهم الأدلة مذكرات عالم الطبيعة لينيوس، وكان في الخامسة والعشرين، عن رحلته إلى لابلاند (شمال السويد) سنة 1732، إذ دوّن فيها كيف كان شعب السامي يلعب لعبة تُسمى «تابلوت».","نُشرت المذكرات مترجمة إلى الإنجليزية سنة 1811، لكن الترجمة احتوت أخطاء. وصارت إعادة بناء موراي (1913) القائمة عليها القاعدة المعتمدة للتافل سنوات طويلة.","ثم صحّح اللاعبون والباحثون الخطأ، وتُلعب اليوم نسخ كثيرة من القواعد. والتافل في الأطلس واحدة منها."],"quiz":[["ما اللعبة التي دوّنها لينيوس في لابلاند؟","تابلوت","سينيت","المنقلة","الشطرنج"],["أي قطعة يحاول المدافعون إيصالها إلى زاوية؟","الملك","الملكة","راية","سفينة"],["متى نُشرت الترجمة الإنجليزية التي فيها الخطأ؟","1811","1732","1932","1066"]],"kf":["ملك وقلة من المدافعين في الوسط، يحيط بهم جيش أكبر عددًا: لعبة طرفين غير متكافئين","لُعبت في شمال أوروبا في عصر الفايكنغ، على ألواح من 7×7 حتى 19×19","وصلتنا القواعد عبر يوميات رحلة لينيوس عام 1732، وعبر ترجمتها الإنجليزية التي فيها أخطاء"],"more":[{"h":"لوح بالينديري","p":["عُثر على لوح بالينديري في مسكن بُني فوق بحيرة (كرانوغ) في وسط أيرلندا، وهو من خشب الطقسوس. وفي ثقوبه الـ49 المرتبة 7×7 كانت تُثبَّت على الأرجح قطع لها وتد في أسفلها.","ويبرز من إطاره مقبض منحوت على هيئة رأس إنسان، فهو لوح يُحمل في السفر. وتذكر المصادر الأيرلندية لعبة تافل 7×7 اسمها «براندوف» (الغراب الأسود)، وربما لُعبت عليه."],"cap":["لوح بالينديري (7×7) وعليه الوضع الابتدائي للعبة «براندوف» الأيرلندية. الحلقات الذهبية تعلّم الوسط والزوايا الأربع"]},{"h":"تابلوت لينيوس","p":["التابلوت الذي دوّنه لينيوس يُلعب على لوح 9×9. يقف الملك على العرش في الوسط، ويواجه «سويديوه» الثمانية ستة عشر «موسكوفيًا».","تتحرك كل القطع في خط مستقيم أي عدد من المربعات كالرخ، وتؤسر إذا حُصرت بين قطعتين للعدو. يفوز المدافعون إذا بلغ الملك الحافة، والمهاجمون إذا أحاطوا به من الجهات الأربع. كتب لينيوس بخليط من اللاتينية والسويدية، فتغيرت عدة نقاط في الترجمة الإنجليزية."],"cap":["التابلوت كما دوّنه لينيوس (9×9): الملك على العرش في الوسط، و8 مدافعين، و16 مهاجمًا. يفوز المدافعون إذا بلغ الملك مربعًا أخضر على الحافة"]},{"h":"ألواح تكبر، ولعبة تختفي","p":["إلى جانب 7×7 كانت هناك ألواح 9×9، ولوح ويلزي 11×11، بل و19×19. وأكبرها «أليا إيفانجيلي» مرسوم في مخطوط من القرن الثاني عشر يقول إنها جاءت من بلاط الملك الإنجليزي أثلستان في القرن العاشر.","ومع انتشار الشطرنج في شمال أوروبا في القرنين الثاني عشر والثالث عشر، تراجعت التافل شيئًا فشيئًا. ولم يبقَ التابلوت إلا في لابلاند البعيدة، فدوّنه لينيوس مصادفة. واليوم تُقام بطولات دولية على ألواح 11×11، وتكسب اللعبة لاعبين جددًا."],"cap":["كنز جزيرة لويس (القرن الثاني عشر): وُجدت مع قطع الشطرنج 14 قرصًا للعبة لوحية"]}],"tl":[["القرن 10","صنع لوح بالينديري في أيرلندا"],["924–939","يُروى أن «أليا إيفانجيلي» لُعبت في بلاط أثلستان"],["القرن 12","رسم «أليا إيفانجيلي» في مخطوط"],["القرنان 12–13","انتشار الشطرنج في شمال أوروبا واختفاء التافل"],["1732","لينيوس يدوّن التابلوت في لابلاند"],["1811","صدور «لاكيسيس لابونيكا»، الترجمة الإنجليزية ليومياته"],["1913","موراي يعيد بناء التافل في «تاريخ الشطرنج»"],["1932","العثور على لوح بالينديري"]]},"goose":{"title":"لعبة الإوزة، هدية لملك","lead":"سباق بالنرد على حلزون من 63 مربعًا أُهدي إلى ملك، ثم لُعب في أوروبا كلها.","s":["لعبة الإوزة سباق: تُرمى النرد ويُتقدَّم على حلزون من 63 مربعًا نحو الهدف في الوسط. من يقف على مربع فيه إوزة يتقدم مرة أخرى بالعدد نفسه. أما البئر والسجن والموت فتوقفك أو تعيدك إلى البداية.","يُعتقد أنها نشأت في إيطاليا في القرن السادس عشر. ويُروى أن فرانشيسكو الأول دي ميديتشي، دوق توسكانا الأكبر، أهدى اللعبة إلى ملك إسبانيا فيليب الثاني بين 1574 و1587.","وفي إنجلترا سجّل الطابع اللندني جون وولف سنة 1597 «لعبة الإوزة الجديدة والممتعة جدًا». وفي القرنين السابع عشر والثامن عشر انتشرت انتشارًا كبيرًا في أوروبا كلها.","طُبعت على الورق وانتشرت في نسخ لا تُحصى برسوم جديدة: لوحات لتعلّم الجغرافيا، ولوحات للحكايات والأمثال، بل ولوحات إعلانية. ويُعتقد أنها كانت نموذجًا لكثير من ألعاب السباق اللاحقة.","في متحف المتروبوليتان للفنون لوحة بوجهين: لعبة الإوزة على وجه والشطرنج على الآخر. يُرجَّح أن حرفيين من غوجارات في الهند صنعوها أواخر القرن السادس عشر، وقد تكون أقدم لوحة باقية للعبة الإوزة."],"quiz":[["كم مربعًا في لعبة الإوزة؟","63","64","100","30"],["من يُروى أنه أهدى اللعبة إلى ملك إسبانيا؟","فرانشيسكو الأول دي ميديتشي","نابليون","إليزابيث الأولى","لويس الرابع عشر"],["ماذا يحدث عند الوقوف على مربع الإوزة؟","تتقدم مرة أخرى بالعدد نفسه","تعود إلى البداية","تخسر دورًا","تتبادل المكان مع خصم"]],"kf":["سباق على حلزون من 63 مربعًا نحو الهدف في الوسط، بحسب رمية النرد","نشأت في إيطاليا في القرن السادس عشر، ويُروى أن آل ميديتشي أهدوها إلى ملك إسبانيا","انتشرت في أوراق مطبوعة، بنسخ لا تُحصى ذات صور وموضوعات جديدة"],"more":[{"h":"حلزون من 63 مربعًا","p":["في النسخة الأشهر توجد إلى جانب الإوز بضعة مربعات خاصة. الجسر في 6 ينقلك إلى 12، وفي النُّزُل عند 19 تخسر دورًا، وفي البئر عند 31 والسجن عند 52 تبقى عالقًا حتى يأتي لاعب آخر فيحررك.","المتاهة في 42 تعيدك إلى 30، والموت في 58 يعيدك إلى البداية. ويجب بلوغ 63 بالرمية المضبوطة، وما زاد يُعَدّ إلى الوراء. والخطوة الأخيرة هي الأصعب."],"cap":["المربعات الـ63 مرتبة حلزونيًا من الخارج إلى الداخل. الأخضر: الإوز؛ الأزرق: الجسر؛ الأصفر: مواضع الانتظار (النُّزُل، البئر، السجن)؛ الأحمر: مواضع الرجوع (المتاهة، الموت)؛ الذهبي: الهدف"]},{"h":"لغز التسعة","p":["يقف الإوز على 5 و9 و14 و18…، بفواصل متناوبة من 4 و5. وعلى كل مضاعف للعدد 9 إوزة، فإذا وقعت رمية 9 على المربع 9 حملتك إلى 18 ثم 27… ومباشرة إلى 63.","لذلك في النسخ التي تُلعب بنردين قاعدة خاصة: إذا كانت الرمية الأولى 6 و3 تذهب إلى 26، وإذا كانت 5 و4 تذهب إلى 53. والعدد 63 هو 7×9، وقد رُبط بسن الثالثة والستين التي كانت تُعدّ آنذاك أخطر أعوام العمر."],"cap":["الإوز يقف كل 4 ثم 5 مربعات بالتناوب، فثمة إوزة دائمًا على مضاعفات 9. لو جاءت 9 في الرمية الأولى لقفز اللاعب من إوزة إلى إوزة حتى 63"]},{"h":"المطبعة تنشرها","p":["طُبعت الألواح من صفائح النحاس وقوالب الخشب فصارت رخيصة. سُمّيت في فرنسا «لعبة الإوزة» (jeu de l’oie) وفي إسبانيا juego de la oca، وما زالت في إسبانيا أهزوجة عن القفز «من إوزة إلى إوزة» مثلًا شائعًا.","وتوالت النسخ ذات الرسوم الجديدة: ألواح لتعلّم الجغرافيا والتاريخ، وأخرى عن الثورة الفرنسية أو نابليون، بل وإعلانات لسلع. وعلى المسار نفسه ذي المربعات الـ63 رسم كل عصر شواغله."],"cap":[]}],"tl":[["القرن 16","يُعتقد أنها نشأت في إيطاليا"],["1574–87","يُروى أن فرانشيسكو الأول دي ميديتشي أهداها إلى فيليب الثاني ملك إسبانيا"],["أواخر القرن 16","صُنع في كجرات (الهند) لوح بوجهين: الإوزة على وجه والشطرنج على الآخر"],["1597","جون وولف يسجّلها للطباعة في لندن"],["القرنان 17–18","رواج في أوروبا كلها وتكاثر النسخ ذات الموضوعات"],["تسعينيات القرن 18","صُنعت ألواح عن الثورة الفرنسية"],["القرن 19","طُبعت بكميات كبيرة في بلدان كثيرة لعبةً للأطفال"]]},"shogi":{"title":"متى وُلدت قاعدة إعادة القطع المأسورة في الشوغي؟","lead":"في عائلة الشطرنج كلها، وحده الشوغي يتيح لك أن تعيد القطعة المأسورة إلى اللوحة لتصبح من قطعك. متى ولماذا ظهرت هذه القاعدة؟","s":["انتشر الجدّ الهندي للشطرنج شرقًا وغربًا، وصار في اليابان شوغي. أقدم قطع شوغي في اليابان 16 قطعة عُثر عليها في أوائل التسعينيات في الحرم القديم لمعبد كوفوكو-جي في نارا. ووُجدت معها بطاقة مؤرخة بعام 1058 (تنكي 6)، لذا يُعتقد أن القطع من الزمن نفسه.","وتذكر كتابات ذلك العصر الشوغي أيضًا. فكتاب «شين ساروغاكو-كي» من منتصف القرن الحادي عشر يذكر اسمه، وكتاب «نيتشوريكي» الذي يجمع سجلات أواخر عصر هييان يصف «شوغي هييان» بالملوك والقادة الذهبيين والفضيين والخيول والرماح والجنود.","وفي عصري كاماكورا وموروماتشي ظهرت أشكال كبيرة كثيرة بقطع أكثر. وأضاف «الشوغي الصغير»، سلف اللعبة الحالية، الرخ والفيل — وقطعة لم تعد موجودة: «الفيل السكران».","يُعتقد أن قاعدة إعادة القطع ظهرت نحو القرن السادس عشر. وتروي التقاليد أن الإمبراطور غو-نارا أمر بإزالة الفيل السكران من الشوغي الصغير، ويُرجَّح أن القاعدة بدأت في ذلك الوقت تقريبًا.","لا يُعرف السبب يقينًا. ومن التفسيرات أن قطع الطرفين بلون واحد ولا تتميز إلا باتجاهها، فيسهل استخدام القطعة المأسورة من جديد. وبفضل هذه القاعدة لا تفرغ اللوحة، والتعادل نادر."],"quiz":[["ما التاريخ المكتوب على البطاقة التي وُجدت مع قطع كوفوكو-جي؟","1058 (تنكي 6)","701 (تايهو 1)","1582 (تينشو 10)","1868 (ميجي 1)"],["متى يُعتقد أن قاعدة إعادة القطع ظهرت؟","نحو القرن السادس عشر","نحو القرن الثامن","نحو القرن التاسع عشر","في القرن العشرين"],["ما السبب المذكور لسهولة إعادة استخدام القطع المأسورة؟","قطع الطرفين بلون واحد وتتميز بالاتجاه","كانت القطع من الذهب","كانت مربعات اللوحة قليلة","كانت القطع تُختار بالنرد"]],"kf":["قريب للشطرنج وُلد في الهند ونشأ في اليابان، ويُلعب على رقعة 9×9","أقدم القطع جاءت من الحرم القديم لمعبد كوفوكو-جي، ووُجدت مع بطاقة مؤرخة بعام 1058","«القطع في اليد» — استعمال القطع المأسورة كأنها لك — نشأت على الأرجح نحو القرن السادس عشر"],"more":[{"h":"لون واحد، والاتجاه هو الفارق","p":["تُطلى قطع الشطرنج بالأبيض والأسود، أما قطع الشوغي فكلها بلون الخشب، ويُعرف صاحب القطعة من اتجاه رأس القطعة الخماسية. وهذا الشكل هو ما يتيح تدوير القطعة المأسورة وإنزالها على الرقعة من جديد.","يُكتب على كل قطعة اسمها، وإذا دخلت معسكر الخصم جاز قلبها «لترقيتها». فيصير البيدق الحرفَ と المكتوب على ظهره ويتحرك كالقائد الذهبي. وكون القطع ألواحًا مسطحة مكتوبة لا تماثيل منحوتة سمةٌ يتشارك فيها الشوغي مع أقاربه في شرق آسيا: الشيانغتشي الصيني والجانغي الكوري."],"cap":["قطع الشوغي بلون واحد للطرفين، وتُميَّز باتجاه رأسها المدبب. على اليمين: بيدق مقلوب «مُرقّى» (توكين)"]},{"h":"عصر الشوغي العملاق","p":["من عصري كاماكورا وموروماتشي حتى عصر إيدو، صُنعت أشكال من الشوغي تكبر شيئًا فشيئًا وتزداد أنواع قطعها. وقد لُعب تشو شوغي ذو الرقعة 12×12 كثيرًا طوال عصر إيدو، وما زال له محبون.","وتذهب السجلات أبعد: داي شوغي 15×15، وتاي شوغي 25×25، وتايكيوكو شوغي بـ804 قطع على رقعة 36×36. لكن اللعبة اليومية كانت شو شوغي 9×9، التي اكتسبت قاعدة القطع في اليد فصارت الشوغي الذي نعرفه."],"cap":["مقارنة أحجام الرقاع مرسومة من زاوية واحدة: 9×9 الشوغي الحالي (40 قطعة)، 12×12 تشو شوغي (92)، 15×15 داي شوغي (130)، 25×25 تاي شوغي (354)، 36×36 تايكيوكو شوغي (804)"]},{"h":"الشوغي في إيدو","p":["في عصر إيدو نشأت بيوت للشوغي تتقاضى رواتب من الشوغونية، ويُعدّ أوهاشي سوكيي أول أساتذتها. وكل عام كان الأفضل يلعبون أمام الشوغون في «مباريات القلعة»، التي ثُبّتت لاحقًا في 17 نوفمبر، ومنها جاء «يوم الشوغي» الحالي.","وكان الشوغي متعة لعامة الناس أيضًا: ففي طبعة هارونوبو زوجان شابان يلعبان بجوار ناموسية. وظهرت كذلك مجموعات من مسائل تسوميه-شوغي كأنها أعمال فنية، مثل «شوغي زوكو» لإيتو كانجو (1755)."],"cap":["طبعة خشبية ملونة لسوزوكي هارونوبو (نحو 1767–69): فتاة وفتى يلعبان الشوغي بجوار ناموسية"]}],"tl":[["1058","قطع من الحرم القديم لكوفوكو-جي (وُجدت مع بطاقة من سنة تنغي 6)"],["منتصف القرن 11","ذكر الشوغي في «شينساروغاكوكي»"],["أوائل كاماكورا","«نيتشوريكي» يعدّد قطع شوغي هييان"],["نحو القرن 16","يُعتقد أن قاعدة القطع في اليد نشأت"],["1612","يُروى أن أوهاشي سوكيي وآخرين تلقوا رواتب من الشوغونية"],["1716","تثبيت مباريات القلعة في 17 نوفمبر"],["1755","«شوغي زوكو» لإيتو كانجو"],["1975","17 نوفمبر يصبح يوم الشوغي"]]},"pachisi":{"title":"كيف صارت البتشيسي لودو","lead":"لعبة لوحة على شكل صليب كانت تُلعب في البلاطات الهندية غيّرت اسمها ووصلت إلى غرف لعب الأطفال في العالم كله.","s":["في الهند لعبتا التشوبار والبتشيسي: يحرّك أربعة لاعبين قطعهم حول لوحة على شكل صليب. يُستخدم في التشوبار نرد طويل (باسا)، وفي البتشيسي أصداف الودع. ومعنى اسم البتشيسي «خمسة وعشرون»، وهو أعلى ما تعطيه رمية الأصداف.","حتى الآلهة كانت تلعب. ففي لوحة من أواخر القرن السابع عشر يجلس الإله شيفا وزوجته بارفاتي أمام لوحة تشوبار على جلد نمر.","وفي فاتحبور سيكري، مدينة الإمبراطور المغولي أكبر (القرن السادس عشر)، ما زالت ساحة تحمل في أرضيتها لوحة ضخمة على شكل صليب. ويُروى أن أكبر كان يلعب مستخدمًا أشخاصًا بملابس ملونة قطعًا.","وفي القرن التاسع عشر عبرت اللعبة البحار. ففي أمريكا بيعت باسم «بارتشيزي» وسُجّلت علامةً تجارية سنة 1874. وفي بريطانيا طُرحت في تسعينيات القرن التاسع عشر باسم «لودو» (باللاتينية «أنا ألعب») وصارت من ألعاب العائلة المفضلة.","اللودو أبسط: نرد واحد، وتخرج القطعة عند الرقم 6. ولها أقارب بأسماء أخرى في أنحاء العالم، مثل «بارتشيس» في إسبانيا و«لا تغضب» (Mensch ärgere Dich nicht) في ألمانيا."],"quiz":[["ما معنى اسم «البتشيسي»؟","خمسة وعشرون","طريق الملك","صليب","صدفة الودع"],["أي مدينة لأكبر ما زالت فيها ساحة بلوحة ضخمة؟","فاتحبور سيكري","قطب منار في دلهي","تاج محل","إلورا"],["ما معنى «لودو» باللاتينية؟","أنا ألعب","أنا أفوز","أنا أركض","أنا أرمي"]],"kf":["لعبة سباق على لوح هندي على شكل صليب: أربعة لاعبين في فريقين يُكملون بقطعهم دورة كاملة","معنى الاسم «25»، وهي أكبر رمية بأصداف الودع","في القرن التاسع عشر عبرت البحار وانتشرت في العالم باسم بارتشيزي ولودو وغيرهما"],"more":[{"h":"الصليب والطريق","p":["لوح البتشيسي صليب تمتد أذرعه الأربع من «التشاركوني» في الوسط. في كل ذراع 3 × 8 مربعات، أي 96 مربعًا في المجموع. وكثيرًا ما كان اللوح يُطرَّز على قماش، فيُلفّ ويُحفظ.","تخرج القطع من المركز، وتنزل في العمود الأوسط من ذراع صاحبها، وتدور حول اللوح مرة عكس عقارب الساعة، ثم تصعد العمود الأوسط عائدة إلى المركز. واللاعبان المتقابلان شريكان، ويفوز الفريق حين يُعيد كلاهما قطعه الأربع."],"cap":["لوح على شكل صليب (كل ذراع 3 × 8 مربعات). الخط الأزرق طريق لاعب واحد: ينزل من وسط ذراعه، ويدور دورة كاملة عكس عقارب الساعة، ثم يصعد من الوسط إلى المركز"]},{"h":"عدّ أصداف الودع","p":["في البتشيسي تُرمى ست أصداف ودع، ويحدد عدد ما سقط منها وفمه إلى أعلى مقدار الحركة. من اثنتين إلى ست يتقدم اللاعب بالعدد نفسه، أما إن كانت واحدة فيتقدم 10، وإن لم تكن أي منها فيتقدم 25.","وباحتمال 1 من 64 يكون 25 أندر الرميات وأكبرها، ومنه أخذت اللعبة اسمها. ورمية 6 أو 10 أو 25 تمنح رمية إضافية. أما التشوبار فيُلعب بثلاثة أحجار نرد طويلة كالعصيّ عليها 1 و2 و5 و6."],"cap":["من ست أصداف ودع: كم واحدة سقطت وفمها إلى أعلى (الصف العلوي)، وكم مربعًا يتقدم اللاعب (الصف السفلي). يُظهر ارتفاع الأعمدة تكرار كل حالة لو سقطت كل صدفة على أي وجه بالتساوي"]},{"h":"أسماء جديدة وبلدان جديدة","p":["عن طريق البريطانيين في الهند وصلت اللعبة إلى أوروبا وأمريكا في القرن التاسع عشر. ففي الولايات المتحدة صارت علامة «بارتشيزي» التجارية، وفي بريطانيا سُجّلت براءة «لودو» عام 1896 بقواعد أبسط ونرد مكعب واحد بدل الأصداف.","وفي ألمانيا ظهرت عام 1914 لعبة «منش إرغره دِش نِشت» («لا تغضب»)، وفي إسبانيا تُلعب «بارتشيس». تتبدل الأسماء والتفاصيل من بلد إلى آخر، لكن الهيكل واحد: الدوران حول الصليب والعودة إلى البيت."],"cap":[]}],"tl":[["القرن 16","إنشاء فناء بلوح صليبي عملاق في فتحبور سيكري مدينة أكبر"],["القرنان 17–18","كثيرًا ما تُصوّر المنمنمات الهندية أناسًا حول التشوبار"],["1694–95","ديفيداسا يرسم شيفا وبارفاتي يلعبان التشوبار"],["1874","«بارتشيزي» علامة تجارية في الولايات المتحدة"],["1896","تسجيل براءة «لودو» في بريطانيا"],["1914","طرح «منش إرغره دِش نِشت» في ألمانيا"]]},"go":{"title":"ما الذي تحكيه لوحة غو عمرها 1300 عام","lead":"لوحة الغو في شوسوئين فيها 19 خطًا كما اليوم — و17 علامة زهرة، على خلاف لوحات اليوم.","s":["وُلدت لعبة الغو في الصين القديمة. وتقول الأسطورة إن الملك الحكيم ياو صنعها ليعلّم ابنه. ويذكر كتاب «منشيوس» الذي يسبق الميلاد اسم أحد أساتذة اللعبة، يي تشيو.","يُعتقد أن حجم اللوحة تغيّر مع الزمن: ففي العصور المبكرة استُخدمت أيضًا لوحات من 17 خطًا، ثم انتشرت لوحة الـ19 خطًا الحالية.","لا يُعرف متى وصل الغو إلى اليابان، لكنه كان يُلعب في عصر نارا. وكانت قواعد الرهبان والراهبات تحظر الموسيقى والقمار، لكنها تسمح بالغو والكوتو — معاملة مختلفة تمامًا عن السوغوروكو.","وصلتنا لوحة الغو المطعّمة في شوسوئين كنزًا مرتبطًا بالإمبراطور شومو. فيها 19 خطًا كما اليوم، لكن فيها 17 علامة زهرة حيث تحمل لوحة اليوم 9 نقاط نجمية. ودُرجاها متصلان: إذا سحبت أحدهما خرج الآخر. ويحفظ شوسوئين أيضًا أحجار غو من العاج المصبوغ بالأحمر والأزرق الداكن، محفورًا عليها طيور.","وفي عصر هييان تصوّر «حكاية غينجي» مشاهد للعب الغو. وفي عصر إيدو خدمت بيوت مثل هون-إنبو الشوغونية، وصار الغو فنًا يتبارى فيه لاعبون محترفون."],"quiz":[["كم خطًا في لوحة الغو بشوسوئين؟","19","17","13","9"],["بماذا سمحت القواعد للرهبان والراهبات؟","الغو والكوتو","السوغوروكو","القمار","الكيماري"],["كم علامة زهرة في لوحة شوسوئين بدل النقاط النجمية؟","17","9","4","25"]],"kf":["حجارة سوداء وبيضاء تُوضع على نقاط تقاطع الخطوط، ويتنافس اللاعبان على تطويق أوسع أرض — لعبة وُلدت في الصين القديمة","بعد عهد ألواح الـ17 خطًا جاءت الـ19؛ ويحفظ شوسوئين لوحًا من 19 خطًا من القرن الثامن","في يابان إيدو خدمت بيوت الغو الشوغونية، وفي القرن الحادي والعشرين هزم ذكاء اصطناعي أفضل لاعب في العالم"],"more":[{"h":"طوِّق لتأسر، وسيِّج لتفوز","p":["في الغو يضع الأسود والأبيض بالتناوب حجارة على نقاط تقاطع الخطوط، ولا يتحرك الحجر بعد وضعه. وإذا امتلأت كل النقاط الخالية المجاورة لحجر (أو مجموعة) بحجارة الخصم أُسر ورُفع عن اللوح.","وفي النهاية يفوز من كان مجموع أرضه المطوَّقة وأسراه أكبر. القواعد قليلة لكن اللوح واسع: فقد حُسب عدد الأوضاع الممكنة على لوح من 19 خطًا بنحو 10 أس 170."],"cap":["طريقة الأسر. يسارًا: للحجر الأسود أربع نقاط خالية بجانبه (بالأحمر). وسطًا: الأبيض يطوّقه من ثلاث جهات فتبقى نقطة. يمينًا: تُسدّ الأخيرة فيؤسر الحجر الأسود"]},{"h":"من 17 خطًا إلى 19","p":["عُثر في قبر من عهد هان الشرقية في وانغدو بإقليم خبي الصيني على لوح غو حجري من 17 خطًا. أما «كتاب الغو» من دونهوانغ، المؤرخ بنحو القرن السادس، فيصف 361 نقطة، أي لوحًا من 19 خطًا. ويبدو أن اللوح كبر فيما بينهما.","لوح شوسوئين من 19 خطًا، لكن بدل نقاط النجوم التسع الحالية فيه علامات زهور في 17 موضعًا. ومجرد الانتقال من 289 نقطة إلى 361 جعل اللعبة أعمق بكثير."],"cap":["مقارنة لوحي الـ17 والـ19 خطًا بعدد النقاط. النقاط السوداء التسع على لوح اليوم هي «نقاط النجوم»"]},{"h":"غو الخالدين، وغو الأساتذة","p":["تحكي قصة صينية عن حطّاب توقف في الجبل يشاهد خالدين يلعبون الغو، ثم انتبه فإذا بسنين كثيرة قد مضت حتى تعفّن مقبض فأسه. وكان الغو بوصفه تسلية الخالدين موضوعًا محببًا على الأطباق واللوحات.","وفي يابان إيدو تلقت بيوت الغو مثل هون-إنبو رواتب من الشوغونية، فصُقل الغو فنًا. وصارت مباراة الوداع التي لعبها هون-إنبو شوساي عام 1938 رواية كاواباتا ياسوناري «معلّم الغو». وفي 2016 هزم الذكاء الاصطناعي ألفاغو أفضل لاعب في العالم لي سي-دول بأربع مباريات مقابل واحدة، فأدهش العالم."],"cap":["طبق من اللك المنحوت عليه خالدون يلعبون الغو (سلالة مينغ، عهد شيوانده، 1425–36)"]}],"tl":[["نحو القرن 4 ق.م","منشيوس يذكر أستاذ الغو يي تشيو"],["هان الشرقية","وضع لوح حجري من 17 خطًا في قبر بوانغدو"],["نحو القرن 6","«كتاب الغو» من دونهوانغ يصف 19 خطًا و361 نقطة"],["القرن 8","لوح الغو المطعّم من خشب الصندل في شوسوئين"],["1612","يُروى أن هون-إنبو سانسا وآخرين تلقوا رواتب من الشوغونية"],["1938","مباراة وداع هون-إنبو شوساي، ثم رواية كاواباتا"],["2016","ألفاغو يهزم لي سي-دول 4–1"]]},"draughts":{"title":"كيف وُلدت لعبة الداما","lead":"لعبة لوحة عربية، ورقعة الشطرنج، ووزير الشطرنج: يُعتقد أن الداما وُلدت من لقاء الثلاثة.","s":["يُعدّ «القِرْق» سلف الداما، وكان يُلعب على شبكة من 5×5 نقاط تصل بينها خطوط، ويرد اسمه في «كتاب الأغاني» من القرن العاشر. ونقله المغاربة إلى إسبانيا فعُرف هناك بـ«ألكيركي»، ودُوّنت قواعده في «كتاب الألعاب» الذي أمر به ألفونسو العاشر ملك قشتالة في القرن الثالث عشر.","ونحو القرن الثاني عشر، في جنوب فرنسا على الأرجح، صار الناس يحرّكون قطع القرق على رقعة الشطرنج، فوُلدت لعبة «فييرج». وسُمّيت القطع باسم وزير الشطرنج آنذاك، «الفرز».","أما الترقية — أن تقوى القطعة إذا بلغت الطرف الآخر — فمذكورة في تأريخ من منتصف القرن الثالث عشر. ولعلها أُخذت من جندي الشطرنج الذي يصير وزيرًا.","وجاء التحول الكبير في فرنسا نحو سنة 1535: أُضيف الأسر الإلزامي — إن استطعت أن تأسر فعليك أن تأسر — وسُمّيت اللعبة «اللعبة المفروضة». ومنها تنحدر الداما الإنجليزية والأمريكية.","وبقيت اللعبة القديمة بلا أسر إلزامي باسم «لعبة السيدات اللطيفة»، ثم قادت لاحقًا إلى الداما الدولية على لوحة 10×10. ومن سلف واحد تفرّعت «ألعاب ملكات» كثيرة."],"quiz":[["ما اللعبة التي تُعدّ سلف الداما؟","القِرْق (ألكيركي)","السينيت","الليوبو","المنقلة"],["متى وأين أُضيف الأسر الإلزامي؟","في فرنسا نحو سنة 1535","في بغداد في القرن العاشر","في أمريكا سنة 1900","في اليابان في القرن الثامن"],["باسم أي شيء سُمّيت قطع لعبة فييرج؟","وزير الشطرنج (الفرز)","ملك الشطرنج","النرد","الفرس"]],"kf":["وُلدت حين نُقلت قطع اللعبة العربية «القِرْق» إلى رقعة الشطرنج","تتحرك القطع قطريًا وتأسر بالقفز، وإذا بلغت الصف الأخير صارت «ملكًا»","أُضيف الأسر الإجباري نحو 1535، وفي 2007 حُلّت اللعبة (8 × 8) حلًا تامًا"],"more":[{"h":"من النقاط والخطوط إلى رقعة الشطرنج","p":["لوح القرق 25 نقطة في شبكة 5 × 5 تصل بينها خطوط. يرصّ كل طرف 12 قطعة، وتبدأ اللعبة من النقطة الوحيدة الخالية في الوسط. تتحرك القطع على الخطوط وتأسر بالقفز فوق قطعة للخصم مجاورة لها.","وحين نُقلت القطع إلى رقعة الشطرنج صار يُستعمل لون واحد من المربعات فقط. في الرقعة 8 × 8 اثنان وثلاثون مربعًا داكنًا، فإذا مُلئت الصفوف الثلاثة الأولى من كل جهة كان لكل طرف 12 قطعة، تمامًا كما في القرق."],"cap":["لوح القرق ووضعه الابتدائي: 5 × 5 نقاط تصل بينها خطوط مستقيمة وقطرية، و12 قطعة لكل طرف، والوسط وحده خالٍ"]},{"h":"اقفز وأسر، ثم كن ملكًا","p":["تتقدم القطع مربعًا واحدًا قطريًا إلى الأمام، وتأسر بالقفز فوق قطعة للخصم مجاورة إذا كان المربع خلفها خاليًا. وإن أمكن بعدها أسر آخر واصلت القفز. وفي قواعد اليوم: من استطاع الأسر وجب عليه.","القطعة التي تبلغ الصف الأخير توضع فوقها قطعة ثانية فتصير ملكًا، ويجوز لها عندئذ التراجع. وفي اللعبة الدولية على رقعة 10 × 10 ينطلق الملك أي مسافة على القطر، فيتغير شكل نهاية الدور كليًا."],"cap":["الأسر والتتويج. القطعة الحمراء تقفز فوق قطعتين بيضاوين متتاليتين فتأسرهما (×)، ثم تبلغ الصف الأخير فتصير ملكًا من قطعتين مكدستين"]},{"h":"لعبة محلولة وعائلة تتسع","p":["في كندا صنع جوناثان شيفر وفريقه برنامج «تشينوك». وفي 1992 لاعب البرنامج ماريون تينسلي، الذي لم يكد يُهزم طوال أكثر من 40 عامًا، ففاز تينسلي. وواصل الفريق الحساب، وأثبت في 2007 أن اللعبة (8 × 8) تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا.","وفي الأثناء تعيش العائلة المتحدرة من السلف نفسه في أنحاء العالم: الداما الدولية 10 × 10، والشاشكي الروسية، والداما التركية بحركاتها المستقيمة، والداما الكندية 12 × 12… وتُقام لها البطولات في كل بلد."],"cap":[]}],"tl":[["القرن 10","«كتاب الأغاني» يذكر القِرْق"],["نحو القرن 12","نشأة «الفييرج»، على الأرجح في جنوب فرنسا"],["1283","«كتاب الألعاب» لألفونسو العاشر يصف القرق"],["نحو 1535","إضافة الأسر الإجباري في فرنسا"],["1547","توركيمادا ينشر في إسبانيا أول كتاب عن الداما"],["القرن 18","انتشار رقعة 10 × 10 في فرنسا وهولندا"],["1992","تينسلي يهزم برنامج «تشينوك»"],["2007","إثبات أن اللعبة (8 × 8) تعادل باللعب المثالي"]]},"reversi":{"title":"ريفرسي وأوثيلو: من اخترعهما؟","lead":"لعبة تحاصر فيها أقراصًا سوداء وبيضاء وتقلبها — ورجلان في إنجلترا القرن التاسع عشر تنازعا عليها.","s":["في لندن ثمانينيات القرن التاسع عشر ادّعى إنجليزيان، لويس ووترمان وجون و. موليت، أن كلًّا منهما مخترع اللعبة، ووصف كلٌّ منهما الآخر بالمحتال.","كانت لعبة موليت «الضمّ» تُلعب على لوحة صليبية الشكل، أما «ريفرسي» ووترمان فاستعملت لوحة عادية 8×8، وشكله هو الذي بقي. بل وصل النزاع على الاسم إلى المحكمة.","انتشرت ريفرسي في أوروبا، وفي سنة 1893 طرحتها شركة رافنسبورغر الألمانية من أوائل منتجاتها. وفي اليابان وُصفت في كتب عصر ميجي وسُمّيت أيضًا «غينبي-غو».","لكن شعبيتها لم تدم. وفي سنة 1971 طرح غورو هاسيغاوا «أوثيلو»، مثبّتًا الافتتاح بوضع الأقراص الأربعة الأولى متقاطعة في الوسط، فصارت هوسًا في اليابان.","ويُقال إن الاسم مأخوذ من مسرحية شكسبير: القائد الأسود البشرة عطيل (أوثيلو) وزوجته البيضاء ديدمونة يذكّران بالأقراص السوداء والبيضاء. وقواعد البطولات اليوم هي قواعد أوثيلو."],"quiz":[["متى وأين عاش الرجلان اللذان تنازعا على ريفرسي؟","إنجلترا، القرن التاسع عشر","فرنسا، القرن الثامن عشر","اليابان، القرن العشرون","إيطاليا، القرن السادس عشر"],["ما شكل لوحة «الضمّ» عند موليت؟","صليب","دائرة","مثلث","مربع 8×8"],["من طرح أوثيلو سنة 1971؟","غورو هاسيغاوا","هون-إنبو شوساكو","لويس ووترمان","رافنسبورغر"]],"kf":["احصر أحجار خصمك بين أحجارك لتقلبها، ومن كانت أحجاره أكثر في النهاية فاز","في لندن ثمانينيات القرن التاسع عشر تنازع إنجليزيان على اختراعها","صارت هوسًا في اليابان في السبعينيات باسم «أوثيلو»، وفي 2023 تبيّن أنها تعادل باللعب المثالي"],"more":[{"h":"احصر واقلب","p":["لا يجوز وضع حجر إلا حيث يحصر صفًّا من أحجار الخصم بينه وبين حجر لك. تمتد الصفوف في ثمانية اتجاهات — أفقية وعمودية وقطرية — وقد تحصر النقلة الواحدة عدة صفوف معًا. وكل حجر محصور يُقلب إلى لونك.","إن لم تكن لك نقلة تُمرّر الدور، وتنتهي اللعبة حين لا يستطيع أي منكما اللعب. أحجار الزوايا لا تُحصر أبدًا، لذا فأخذ زاوية ميزة كبيرة. ويهتم اللاعبون الأقوياء بتقليل الأماكن المتاحة لخصمهم أكثر من عدد أحجارهم في اللحظة."],"cap":["طريقة القلب. حجر أسود يوضع في المربع ذي الحلقة الحمراء يحصر البيض في ثلاثة اتجاهات — أفقيًا وعموديًا وقطريًا — فتنقلب الأحجار السبعة ذات الإطار الذهبي سوداء"]},{"h":"الأحجار الأربعة الأولى","p":["في الريفرسي القديمة كان اللاعبان يضعان بالتناوب الأحجار الأربعة الأولى في المربعات الأربعة الوسطى، فقد تأتي البداية متجاورة أو متقاطعة.","وثبّتت أوثيلو البداية المتقاطعة. فمنذ النقلة الأولى يسهل حصر اللونين، فيبدأ الصراع فورًا. وتنطلق بطولات العالم اليوم من هذا الوضع."],"cap":["الأحجار الأربعة الأولى. يسارًا: بداية ممكنة للريفرسي القديمة (اللونان متجاوران). يمينًا: البداية المتقاطعة التي ثبّتتها أوثيلو"]},{"h":"البشر والحواسيب","p":["انتشرت أوثيلو من اليابان إلى العالم، وأُقيمت أول بطولة عالمية لها في طوكيو عام 1977. القواعد بسيطة، فيصنع الفارقَ عمقُ الحساب، ويرى كبار اللاعبين عشرات النقلات مقدمًا.","في 1997 لعب برنامج «لوجيستيلو» ست مباريات مع بطل العالم تاكيشي موراكامي وفاز بها كلها. وفي 2023 أظهرت الحسابات أن أوثيلو 8 × 8 تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا."],"cap":[]}],"tl":[["ثمانينيات القرن 19","ووترمان وموليت يتنازعان الاختراع في لندن"],["1893","رافنسبورغر في ألمانيا تطرح «ريفرسي»"],["عصر ميجي","كتب يابانية تقدمها باسم «غينبي-غو»"],["1973","طرح مجموعات أوثيلو في اليابان"],["1977","أول بطولة عالم لأوثيلو في طوكيو"],["1997","لوجيستيلو يهزم بطل العالم تاكيشي موراكامي 6–0"],["2023","إظهار أن أوثيلو 8 × 8 تعادل باللعب المثالي"]]},"mancala":{"title":"أين وُلدت المنقلة؟","lead":"لعبة تُوزَّع فيها الحصى من حفرة إلى حفرة كما تُبذر البذور، تُلعب في أفريقيا وآسيا بمئات الأسماء.","s":["المنقلة اسم لعائلة ألعاب تُؤخذ فيها الحصى أو البذور من حفرة وتُبذر واحدة واحدة في الحفر التالية. ويُقال إن الكلمة من الفعل العربي «نَقَلَ».","تتبدّل الأسماء والقواعد من مكان إلى آخر — الأواري في غرب أفريقيا، والباو في شرقها، والمانغالا في تركيا، والكونغكاك في جنوب شرق آسيا، ومئات غيرها — بصفّين أو أربعة وبأي عدد من الحفر.","كثيرًا ما يُقال إنها قديمة جدًا، لكن الأدلة الثابتة أحدث مما يُظن. فأقدم الألواح الثابتة التاريخ حتى الآن ألواح من الفخار والحجر من نحو القرنين السادس والسابع، عُثر عليها في مواقع مملكة أكسوم القديمة في ماطرة ويحا (إريتريا وإثيوبيا).","وقد اقتُرحت أمثلة أقدم، لكن لا يُعرف إن كانت صفوف الثقوب تلك للمنقلة حقًا، والباحثون مختلفون. ومن الآراء القوية أن اللعبة انتشرت من أكسوم إلى جزيرة العرب وداخل أفريقيا.","ولا تظهر أوصاف كاملة لطريقة اللعب إلا نحو القرن السابع عشر. وفي الأطلس يمكنك لعب المنقلة بثماني قواعد، منها الأواري والمانغالا."],"quiz":[["ما معنى الكلمة العربية التي جاءت منها «المنقلة»؟","نَقَلَ","بذرة","حفرة","ملك"],["أين عُثر على أقدم ألواح المنقلة الثابتة التاريخ؟","في مواقع مملكة أكسوم القديمة (إثيوبيا وإريتريا)","في الكولوسيوم بروما","على سور الصين العظيم","في ستونهنج"],["أي منقلة تُلعب في غرب أفريقيا؟","الأواري","الليوبو","التافل","البتشيسي"]],"kf":["عائلة من ألعاب «البذر»: تُرفع البذور من حفرة وتُلقى واحدة واحدة في الحفر التالية","أقدم الألواح المؤرخة بثقة من مملكة أكسوم القديمة، نحو القرنين السادس والسابع","صفّان أو أربعة، بمخازن أو بدونها: يتغير اللوح والقواعد من منطقة إلى أخرى"],"more":[{"h":"البذر","p":["في المنقلة تختار حفرة في جهتك، وترفع كل بذورها، ثم تلقيها واحدة واحدة في الحفر التالية. وتُسمّى هذه الحركة، الشبيهة بنثر البذور في الحقل، بذرًا.","تبدأ الأواري من غرب أفريقيا بـ48 بذرة، أربعًا في كل حفرة من الحفر الاثنتي عشرة. فإذا جعلت البذرة الأخيرة حفرة للخصم اثنتين أو ثلاثًا أخذتَها. ومعرفة أين ينتهي البذر — أي العدّ مسبقًا — هي كل شيء. وقد عبرت الأواري الأطلسي وتُلعب أيضًا في جزر الكاريبي."],"cap":["البذر في الأواري. تُوزَّع البذور الثلاث من الحفرة ذات الحلقة الذهبية واحدة واحدة عكس عقارب الساعة، فتجعل الأخيرة حفرة الخصم ثلاثًا تمامًا فتُؤخذ الثلاث (الحلقة الحمراء)"]},{"h":"صفّان وأربعة","p":["تنقسم ألواح المنقلة عمومًا إلى ذات صفين وذات أربعة صفوف. تكثر ذات الصفين في غرب أفريقيا وآسيا، وتمتد ذات الأربعة من شرق أفريقيا إلى جنوبها. والباو التنزانية أربعة صفوف من 8 حفر، واسمها بالسواحلية يعني ببساطة «اللوح».","وفي بعضها، مثل الكونغكاك والسونغكا في جنوب شرق آسيا، حفرة كبيرة في كل طرف — مخزن — للبذور المأخوذة. و«كالاه» التي وُلدت في أمريكا في القرن العشرين لعبة بصفين ومخزنين، وقد أظهر الحساب عام 2000 أن كالاه بست حفر وأربع بذور في كل منها يفوز بها اللاعب الأول دائمًا."],"cap":["أمثلة لألواح المنقلة: صفّان من 6 (الأواري وغيرها)، صفّان من 7 مع مخزن في كل طرف (الكونغكاك في جنوب شرق آسيا وغيرها)، أربعة صفوف من 8 (الباو في شرق أفريقيا وغيرها)"]},{"h":"من دوّنوها","p":["يُقال عادة إن أول عالم أوروبي وصف المنقلة بالتفصيل هو الإنجليزي توماس هايد، الذي ذكر في كتابه «عن الألعاب الشرقية» (1694) اسمها العربي وطريقة لعبها.","وفي 1836 دوّن إدوارد و. لين، وهو يصف الحياة اليومية في القاهرة، «المنقلة» التي كانت تُلعب في المقاهي. واليوم جمع الباحثون ألعابًا من كل مكان، وتبلغ القواعد المدوّنة المئات."],"cap":[]}],"tl":[["القرنان 6–7","أقدم الألواح المؤرخة بثقة، من مواقع أكسوم"],["1694","توماس هايد يصف المنقلة في «عن الألعاب الشرقية»"],["القرنان 18–19","الأواري وغيرها تعبر الأطلسي إلى الكاريبي"],["1836","إ. و. لين يدوّن منقلة القاهرة"],["منتصف القرن 20","طرح «كالاه» ذات الصفين والمخزنين في الولايات المتحدة"],["2000","حساب يُظهر أن كالاه بست حفر وأربع بذور فوز للاعب الأول"]]},"morris":{"title":"لعبة الطاحونة في كل مكان","lead":"سقف معبد، وسفينة فايكنغ، ومقعد حجري في كاتدرائية: نُقشت خطوطها حيثما جلس الناس معًا.","s":["في لعبة الطاحونة (الحجّة) يضع كل لاعب تسع قطع على 24 نقطة في ثلاثة مربعات متداخلة؛ وثلاث في صف واحد — «طاحونة» — تُزيل قطعة من الخصم. والاسم الإنجليزي «موريس» لا علاقة له بالرقص، ويُقال إنه من اللاتينية merellus أي القطعة أو الفيشة.","كثيرًا ما تُقدَّم لوحة منقوشة على بلاطة سقف معبد القرنة في مصر على أنها الأقدم، نحو 1400 ق.م. لكن الباحث فريدريش برغر لاحظ صلبانًا قبطية بين النقوش نفسها، وخلص إلى أنه لا يمكن تأريخها. أما الأمثلة المؤكدة فتبدأ في العصر الروماني.","وفي سفينة غوكستاد النرويجية، نحو سنة 900، نُقشت لوحة على لوح من سطح السفينة. وفي إنجلترا بقيت لوحات على المقاعد الحجرية في أروقة كاتدرائيات مثل كانتربري وسالزبري.","ويُظهرها «كتاب الألعاب» لألفونسو العاشر (1283) وهي تُلعب بالنرد أيضًا. وكتب شكسبير في «حلم ليلة منتصف الصيف» أن الأمطار ملأت «الطاحونة» بالطين: لوحة محفورة في مرج القرية.","وفي 1996 فحص الألماني رالف غاسر كل الأوضاع بالحاسوب وأثبت أن اللعب المثالي من الطرفين ينتهي بالتعادل. ومع ذلك تبقى بين شخصين لعبة ممتازة."],"quiz":[["من أين يُقال إن اسم «موريس» جاء؟","من اللاتينية «قطعة اللعب»","من رقصة إنجليزية","من اسم شخص","من اسم سفينة"],["ماذا لاحظ الباحثون عن لوحات معبد القرنة؟","لا يمكن تأريخها","مصنوعة من الذهب","جاءت من الصين","كانت لإمبراطور"],["ماذا أثبت الحاسوب في 1996؟","اللعب المثالي ينتهي بالتعادل","البادئ يفوز دائمًا","الثاني يفوز دائمًا","تكفي ثماني قطع"]],"kf":["تسع قطع لكل لاعب على 24 نقطة في ثلاثة مربعات متداخلة؛ وثلاث في صف واحد تُسقط قطعة للخصم","منذ العصر الروماني نُقش لوحها حيث اجتمع الناس: على أسطح السفن ومقاعد الكاتدرائيات","في 1996 فُحصت كل الأوضاع بالحاسوب: باللعب المثالي تنتهي بالتعادل"],"more":[{"h":"ضَع، حرِّك، طِر","p":["تمر اللعبة بثلاث مراحل. أولًا يضع اللاعبان بالتناوب قطعهما التسع على النقاط الخالية. وبعد وضعها كلها تُحرَّك قطعة واحدة كل مرة على خط إلى نقطة مجاورة خالية.","ثلاث من قطعك في صف واحد على خط تكوّن «طاحونة»، فترفع قطعة للخصم عن اللوح. وفي قاعدة شائعة يجوز لمن بقيت له ثلاث قطع أن «يطير» إلى أي نقطة خالية. ويخسر من بقيت له قطعتان أو عجز عن الحركة."],"cap":["لوح الطاحونة. كوّن الأبيض طاحونة على الضلع الخارجي (بالذهبي)، فيحق له أخذ قطعة سوداء (الإشارة الحمراء)"]},{"h":"من ثلاث قطع إلى اثنتي عشرة","p":["تُسمّى هذه العائلة بعدد قطعها. طاحونة الثلاث، بثلاث قطع لكل لاعب، لوح صغير قريب من «إكس-أو». وطاحونة الست تستعمل لوحًا من مربعين متداخلين.","أما طاحونة الاثنتي عشرة فتضيف خطوطًا قطرية إلى لوح طاحونة التسع. وفي جنوب أفريقيا تُسمّى «مورابارابا»، ويُقال إن صبية الرعاة كانوا يرسمونها على الأرض، ولها اليوم بطولات."],"cap":["مقارنة الألواح. العدد هو قطع كل لاعب: طاحونة الثلاث والست والتسع والاثنتي عشرة"]},{"h":"بطل شطرنج وحاسوب","p":["وكان بطل العالم في الشطرنج إيمانويل لاسكر ممن شُغفوا بهذه اللعبة. ففي كتابه «ألعاب الألواح عند الشعوب» (1931) اقترح نسخة بعشر قطع لكل لاعب، يجوز فيها التحريك قبل وضع كل القطع.","وفي 1996 جمع السويسري رالف غاسر جداول كاملة لأوضاع النهاية مع بحث يبدأ من الافتتاح، فأثبت أن الطاحونة تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا. للوح 24 نقطة فقط، لكن عدد الأوضاع يبلغ المليارات."],"cap":[]}],"tl":[["العصر الروماني","نقش ألواح على الحجر في أنحاء الإمبراطورية (أول الأمثلة المؤكدة)"],["نحو 900","نقش لوح على خشبة من سطح سفينة غوكستاد (النرويج)"],["1283","«كتاب الألعاب» لألفونسو العاشر يصوّر الطاحونة"],["العصور الوسطى","ألواح منقوشة على مقاعد أروقة الكاتدرائيات الإنجليزية"],["تسعينيات القرن 16","«حلم ليلة صيف» لشكسبير يذكر لوحًا امتلأ بالطين"],["1931","لاسكر يقترح نسخة جديدة في «ألعاب الألواح عند الشعوب»"],["1996","غاسر يثبت التعادل باللعب المثالي"]]},"patolli":{"title":"باتولّي، سباق الفاصولياء عند الأزتك","lead":"لوحة على شكل صليب، وفاصولياء بدل النرد: لعبة اشتدت فيها المراهنات حتى منعها الإسبان.","s":["كانت باتولّي لعبة سباق عند الأزتك في المكسيك، ومعنى اسمها «الفاصولياء»: تُرمى خمس حبات حمراء معلَّمة أو مثقوبة من جهة، وتتقدّم القطع بعدد العلامات الظاهرة على مسار صليبي الشكل مرسوم على حصير أو على الأرض.","وكتب دييغو دوران، الذي وصف المنطقة في القرن السادس عشر، أن اللاعبين كانوا يحرقون البخور ويدعون الحبات قبل الرمي، ويطلبون الفوز من ماكويلشوتشيتل إله الألعاب.","وكان النبلاء يراهنون بالجواهر والعباءات بل بأنفسهم، فصار بعض الخاسرين عبيدًا. ويُروى أيضًا أن الإمبراطور موكتيزوما كان يشاهد نبلاءه وهم يلعبون.","ونفر الرهبان الإسبان من المراهنة والدعاء للآلهة القديمة، فمنعوا باتولّي وكسروا الحُصر وأحرقوا الحبات، لذلك لم يبقَ إلا القليل من أدواتها. ومع ذلك عُثر على لوحات منقوشة في أرضيات حجرية وصخور في تيوتيهواكان ومواقع المايا، وفي 1977 بين نقوش صخرية في خاليسكو.","واللوحة الصليبية التي تدور عليها القطع تشبه كثيرًا لعبة البتشيسي الهندية. وفي 1878 رأى الإنجليزي إ. ب. تايلور أن أصلها آسيوي، أما اليوم فيرى أكثر الباحثين أن اللعبتين نشأتا كلٌّ على حدة."],"quiz":[["ماذا كان يُرمى في باتولّي بدل النرد؟","حبات فاصولياء معلَّمة","عظام حيوانات","أصداف","عصيّ خشبية"],["لماذا مُنعت باتولّي بحسب السجلات؟","المراهنة والدعاء للآلهة القديمة","كانت اللوحة كبيرة جدًا","كانت الحبات غالية","خسر الملك"],["أي لعبة تشبه لوحتها لوحة باتولّي كثيرًا؟","البتشيسي","الغو","الداما","المنقلة"]],"kf":["لعبة سباق أزتيكية: تُرمى خمس حبات فاصولياء معلَّمة وتُحرَّك القطع على لوح على شكل صليب","لارتباطها بالرهان والدعاء للآلهة، حظرها الرهبان الإسبان","تشبه البتشيسي الهندية شبهًا مدهشًا، لكن يُعتقد أن كلتيهما نشأت مستقلة"],"more":[{"h":"طريق صليبي من 52 مربعًا","p":["لوح الباتولّي طريق على شكل صليب يُرسم على قماش أو حصير أو أرض حجرية. وتمنح إعادات البناء عادةً كل ذراع من الأذرع الأربع مسارين من المربعات، تبلغ مع مربعات الوسط الأربعة 52 مربعًا.","واثنان وخمسون هو أيضًا عدد سنوات دورة التقويم الأزتيكي، ولذا يرى بعض الباحثين في اللوح صورة للتقويم أو لمرور الزمن. وكان اللاعبون يدورون بقطعهم دورة كاملة، ويفوز أول من يعود."],"cap":["لوح باتولّي كما يُعاد بناؤه عادة: أربع أذرع في كل منها مساران من ستة مربعات، إضافة إلى أربعة مربعات في الوسط، فالمجموع 52. ويُظن أن المربعات الحمراء في أطراف الأذرع خاصة"]},{"h":"خمس حبات","p":["بدل النرد كانت تُرمى خمس حبات فاصولياء في أحد وجهيها ثقب أو علامة، ويتقدم اللاعب بعدد العلامات الظاهرة. ولا تظهر العلامات الخمس معًا إلا مرة في كل 32 رمية.","ويُروى أنهم كانوا قبل الرمي يخاطبون الحبات ويستنجدون بماكويلشوتشيتل إله الألعاب. وفي «مخطوط ماليابيكيانو» من القرن السادس عشر أناس حول لوح باتولّي تحت عين الإله."],"cap":["من خمس حبات: كم واحدة تسقط ووجهها المعلَّم إلى أعلى (0–5) وكم مرة (من 32)، لو سقطت كل حبة على أي وجه بالتساوي"]},{"h":"شبيه البتشيسي","p":["قطع تدور حول لوح صليبي، وحركة تتحدد بعدد ما سقط من الأدوات المرمية ووجهه إلى أعلى: الباتولّي والبتشيسي أو التشوبار الهندية متشابهة على نحو مذهل. وفي 1878 رأى عالم الأنثروبولوجيا البريطاني تايلور أن ذلك ليس مصادفة، بل علامة على أن اللعبة جاءت من آسيا.","لكن لم يُعثر على أي دليل على عبور كهذا للمحيطات. ويرى أكثر الباحثين اليوم أن أناسًا في أماكن مختلفة اهتدوا كلٌّ بنفسه إلى الفكرتين ذاتهما: طريق يدور، وأشياء تُرمى."],"cap":["لوحة للتشوبار في الهند (1694–95): قطع تدور حول لوح صليبي، كما في الباتولّي"]}],"tl":[["عصر تيوتيهواكان","نقش ألواح صليبية في أرضيات حجرية"],["1519–21","إسبانيا تغزو الأزتيك"],["القرن 16","«مخطوط ماليابيكيانو» يصوّر الباتولّي وماكويلشوتشيتل"],["نحو 1577","ساهاغون يدوّن الباتولّي في «مخطوط فلورنسا»"],["نحو 1581","دوران يصف الصلوات والرهان"],["1878","تايلور يطرح أصلًا آسيويًا"],["1977","العثور على لوح بين النقوش الصخرية في خاليسكو"]]},"xiangqi":{"title":"نهر شيانغتشي ومدفعها","lead":"«نهر» في الوسط ومدفع يقفز ليأسر: متى اتخذ الشطرنج الصيني شكله الحالي؟","s":["شيانغتشي هو الشطرنج الصيني، ويُلعب على نقاط شبكة 9×10. قطعه أقراص مستديرة عليها حروف، وتتحرك على الخطوط لا داخل المربعات كما في الشطرنج.","ومن الخيوط المبكرة كتاب «شيوانغواي لو»، مجموعة الحكايات الغريبة لوزير أسرة تانغ نيو سنغرو (779–847). ففي حلم رجل عن جيش صغير جدًا يُذكر الحصان السماوي والقائد والعربات والمشاة، مع إشارات إلى منجنيق. لكن اللوحة والحركات لم تكن كما هي اليوم.","أما الشكل الحالي — لوحة 9×10 والنهر والمدفع — فيظهر في سجلات أسرة سونغ (960–1279). وعُثر على طقم كامل من القطع في قبر من عهد سونغ الشمالية في لوويانغ.","وكثيرًا ما يُكتب على النهر «نهر تشو، حدود هان»، نسبةً إلى الحد بين دولة تشو بقيادة شيانغ يو ودولة هان بقيادة ليو بانغ في حربهما في القرن الثالث ق.م. ولا يخرج القائد من قصره، ولا يجوز أن يتقابل القائدان من غير قطعة بينهما.","ولا يأسر المدفع إلا بالقفز فوق قطعة واحدة بالضبط. ويحب الفيتناميون شيانغتشي باسم «كو تونغ»، وفي كوريا نشأت منها قريبتها «جانغي». وفي الأطلس يمكنك لعب الاثنتين."],"quiz":[["أين تتحرك قطع شيانغتشي؟","على نقاط الخطوط","داخل المربعات","حول دائرة","على مسدّسات"],["في سجلات أي أسرة يظهر شيانغتشي الحالي؟","سونغ","هان","مينغ","تشينغ"],["كيف يأسر المدفع؟","بالقفز فوق قطعة واحدة","خطوة مستقيمة","خطوتان قطريًا","فقط بعد عبور النهر"]],"kf":["الشطرنج الصيني: قطع مستديرة مكتوب عليها تتقاتل على نقاط شبكة من 9 × 10 خطوط","يعبر «نهر» وسط الرقعة، ولكل طرف «قصر» لقائده؛ ولكل قطعة مجالها","اتخذت شكلها الحالي في عهد سونغ، وما زال يلعبها عشرات الملايين في الصين وفيتنام"],"more":[{"h":"رقعة بنهر وقصرين","p":["لكل طرف 16 قطعة: قائد، ومستشاران، وفيلان، وحصانان، وعربتان، ومدفعان، وخمسة جنود. ويكتب الأحمر والأسود بعض القطع ذات الدور الواحد بحروف مختلفة قليلًا.","لا يغادر القائد ولا المستشاران القصر، ولا يعبر الفيلان النهر. ويتقدم الجنود إلى الأمام فقط حتى يعبروا النهر، ثم يجوز لهم التحرك جانبًا أيضًا. ولا يقفز الحصان إذا كانت بجانبه مباشرة قطعة في الاتجاه الذي يريده. فبنية الرقعة نفسها تحدد دور كل قطعة."],"cap":["الوضع الابتدائي في شيانغتشي. الأسود أعلى والأحمر أسفل. يدل الحرفان 楚河 漢界 على النهر، والمربعات 3 × 3 ذات الأقطار هي القصران"]},{"h":"المدفع القافز","p":["يتحرك المدفع عادة كالعربة أي مسافة على الخط. لكنه لكي يأسر يجب أن يقفز فوق قطعة واحدة بالضبط بينه وبين الهدف، من أي لون، تُسمّى الحاجز.","واستعمال القطع حواجز يولّد تكتيكات لا توجد في أي لعبة أخرى. ونقل المدفع إلى العمود الأوسط في البداية — «المدفع الأوسط» — ما زال من أكثر الافتتاحات شيوعًا."],"cap":["كيف يأسر المدفع: يقفز المدفع الأحمر فوق قطعة واحدة بالضبط بينهما — الحصان الأسود — ليأسر العربة السوداء خلفها"]},{"h":"سجلات الأدوار والأساتذة","p":["في عهد مينغ صدرت كتب كثيرة تجمع أدوارًا جميلة ومسائل. ويُعدّ «شيتشينغ ياتشو» (1570) و«جوجونغ مي» (1632) من الكلاسيكيات التي ما زالت تُدرس.","وفي القرن العشرين فاز هو رونغهوا ببطولة الصين الوطنية عشر مرات متتالية، وفي 1993 تأسس الاتحاد العالمي لشيانغتشي فبدأت البطولات الدولية. وفي حدائق الصين وفيتنام تتشكل كل يوم حلقات من المتفرجين حول الرقعة."],"cap":[]}],"tl":[["القرن 9","«شيوانغواي لو» لنيو سنغرو يذكر القائد والعربة والحصان"],["سونغ (960–1279)","ظهور الشكل الحالي برقعة 9 × 10 ونهر ومدفع في السجلات"],["سونغ الشمالية","وضع طقم قطع كامل في قبر بلويانغ"],["1570","مجموعة الأدوار «شيتشينغ ياتشو»"],["1632","مجموعة الأدوار «جوجونغ مي»"],["الستينيات–السبعينيات","هو رونغهوا يفوز بعشرة ألقاب وطنية متتالية"],["1993","تأسيس الاتحاد العالمي لشيانغتشي"]]},"backgammon":{"title":"هل عمر الطاولة 5000 عام؟","lead":"اللوحة التي تُسمّى «أقدم طاولة» والأسلاف الحقيقيون للعبة: من بلاط فارسي إلى نوادي نيويورك.","s":["كشفت «المدينة المحروقة» شهر سوخته في إيران عن لوحة عمرها نحو 5000 عام مع 60 قطعة ونرد، وكثيرًا ما تُسمّى أقدم طاولة. لكن خاناتها تصنعها التفافات أفعى منحوتة، نحو عشرين خانة، وشكلها يختلف عن اللعبة الحالية.","والسلف المباشر المحتمل للطاولة هو «النرد» الفارسي الذي ظهر بين القرنين الثالث والسادس. وتروي حكاية بالفارسية الوسطى كُتبت بين القرنين السابع والتاسع أن الوزير بزرجمهر حلّ لغز الشطرنج المرسل من الهند، ثم اخترع النرد ردًّا عليه.","وكان لروما لعبتها اللوحية بثلاثة أحجار نرد، «تابولا» — وهي لعبة الإمبراطور زينون السيئة الحظ في الحكاية 3. وانتشرت عائلة «الطاولات» هذه في أوروبا كلها وأنجبت أقارب كثيرين مثل التريكتراك الفرنسي.","ويظهر اسم «باكغامون» في إنجلترا القرن السابع عشر، وفي 1743 نشر إدموند هويل قواعدها واستراتيجيتها.","وآخر اختراع كبير، مكعب المضاعفة، يُقال إنه وُلد في نوادي نيويورك في عشرينيات القرن العشرين. فبإمكانه مضاعفة الرهان في منتصف الدور، صارت الطاولة لعبة عميقة تقوم على معرفة متى تضغط."],"quiz":[["ما شكل لوحة شهر سوخته؟","خانات من التفافات أفعى","مثل الطاولة الحالية","قرص مستدير","صليب"],["بحسب الحكاية، من اخترع النرد؟","الوزير بزرجمهر","الإمبراطور زينون","إدموند هويل","ألفونسو العاشر"],["ما الذي يُقال إنه وُلد في نيويورك في العشرينيات؟","مكعب المضاعفة","حجرا النرد","الخانات الـ24","القطع الخمس عشرة"]],"kf":["خمس عشرة قطعة لكل طرف تتسابق على 24 مثلثًا برمي نردين، ومن أخرجها كلها أولًا فاز","أسلافها المباشرون «النرد» الفارسي و«التابولا» الرومانية من عائلة «الطاولات»","أضاف مكعب المضاعفة والحواسيب إليها عمقًا جديدًا في القرن العشرين"],"more":[{"h":"خمس عشرة قطعة و24 خانة","p":["في اللوح 24 مثلثًا طويلًا تُسمّى خانات، ولكل لاعب 15 قطعة. يُرمى نردان، وتُحرَّك قطعة لكل رقم، أو قطعة واحدة بالرقمين. وإذا جاء زوج متماثل استُعمل الرقم أربع مرات.","من يقف على قطعة منفردة للخصم «يضربها» ويرسلها إلى الحاجز في الوسط، وعليها أن تدخل من جديد عبر بيت الخصم. فإذا اجتمعت القطع الخمس عشرة في البيت بدأ إخراجها من اللوح، ومن أنهى أولًا فاز."],"cap":["الوضع الابتدائي للطاولة. يتحرك الأبيض من 24 إلى 1 (عكس عقارب الساعة)، والخانات 1–6 أسفل اليمين بيته. ويتحرك الأسود في الاتجاه المعاكس"]},{"h":"كلما اقتربت سهُل الضرب","p":["تتوقف القدرة على ضرب قطعة منفردة كثيرًا على المسافة. فمن ست خانات تصيب 17 رمية من 36، ومن سبع لا تصيب إلا 6.","ومعرفة هذه الأرقام تكشف أين تكون القطعة في خطر. في البداية يحتاج كل لاعب إلى 167 نقطة نرد ليعيد كل قطعه ويخرجها، ويعدّ الأقوياء هذا «العدّ» ليحكموا من المتقدم."],"cap":["كم من رميات النردين الـ36 تستطيع ضرب قطعة منفردة على بعد 1–12 خانة (إن لم يعترض الطريق شيء)"]},{"h":"من النوادي إلى بطولات العالم","p":["في 1743 نشر إدموند هويل في إنجلترا كتابًا في القواعد والخطط. وفي بريطانيا القرن التاسع عشر أُحبت اللعبة حتى رُسمت على الأثاث، وفي نوادي نيويورك في العشرينيات وُلد مكعب المضاعفة.","وفي 1964 أُقيمت بطولة عالمية في جزر البهاما، وانتشرت اللعبة انتشارًا كبيرًا في السبعينيات. وفي 1979 هزم برنامج هانز برلينر بطل العالم لويجي فيلا، ونحو 1992 بلغ «تي دي-غامون»، الذي يتعلم باللعب ضد نفسه، قوة تقارب أفضل البشر."],"cap":["خزانة رُسم عليها لاعبا طاولة (لندن، 1861)، من أوائل أعمال شركة موريس ومارشال وفوكنر"]}],"tl":[["نحو 3000 ق.م","دفن لوح على شكل أفعى ملتفة وقطع ونرد في شهر سوخته"],["نحو القرون 3–6","ظهور النرد في فارس"],["1743","هويل ينشر كتابه عن الطاولة"],["العشرينيات","ولادة مكعب المضاعفة في نيويورك"],["1964","بطولة عالمية في البهاما"],["1979","برنامج برلينر يهزم بطل العالم"],["نحو 1992","ظهور «تي دي-غامون» الذي يتعلم باللعب ضد نفسه"]]},"hex":{"title":"هيكس، اختُرعت مرتين","lead":"شاعر دنماركي وعبقري أمريكي شاب ابتكرا اللعبة نفسها، كلٌّ منهما من غير أن يعرف بالآخر.","s":["في هيكس يضع اللاعبان الأحجار بالتناوب على معيَّن من السداسيات، ومن يصل بين ضلعيه المتقابلين يفوز. هذا كل شيء.","وأول من فكّر فيها الرياضي والشاعر الدنماركي بيت هاين. ففي 1942 عرضها في معهد نيلز بور في كوبنهاغن، وفي 26 ديسمبر من السنة نفسها نشرتها صحيفة «بوليتيكن» باسم «بوليغون»، وبيعت في دفاتر من 50 ورقة.","وفي 1943 اضطر هاين إلى مغادرة الدنمارك فاختفت اللعبة. وبعد سنوات قليلة، في 1948–1949، ابتكر جون ناش، طالب الدراسات العليا في برينستون، اللعبة نفسها مستقلًا تمامًا، ويُقال إن زملاءه سمّوها «ناش».","وفي 1952 طرحتها شركة باركر براذرز باسم «هيكس»، وفي 1957 قدّمها مارتن غاردنر في عموده في مجلة ساينتفك أمريكان فعرفها العالم.","ولا تنتهي هيكس بالتعادل أبدًا. وقد أثبت ناش أن اللاعب الأول يملك دائمًا استراتيجية رابحة، من غير أن يبيّنها. وعلى اللوحات الكبيرة ما زال طريق الفوز هذا مجهولًا."],"quiz":[["كيف تفوز في هيكس؟","بوصل ضلعيك","بأسر كل الأحجار","بمحاصرة الملك","بخمسة في صف"],["ما اسم لعبة هاين في الصحيفة الدنماركية؟","بوليغون","ناش","كون-تاك-تيكس","أوثيلو"],["ماذا أثبت ناش؟","اللاعب الأول يستطيع الفوز دائمًا","الثاني يفوز دائمًا","تنتهي دائمًا بالتعادل","النقلات الرابحة بالضبط"]],"kf":["تُوضع الحجارة بالتناوب على خلايا سداسية، ويفوز من يصل ضلعيه المتقابلين بلونه","اخترعها بيت هاين في الدنمارك (1942) وجون ناش في أمريكا (1948–49) كلٌّ على حدة","لا تعادل فيها، وقد ثبت أن اللاعب الأول يفوز — لكن لا أحد يعرف كيف على الألواح الكبيرة"],"more":[{"h":"لعبة وصل","p":["اللوح معيّن من خلايا سداسية، ومقاسه الرسمي 11 × 11. للأحمر الضلعان الأعلى والأسفل، وللأزرق الأيسر والأيمن، ويضعان حجرًا واحدًا بالتناوب. ولا تتحرك الحجارة أبدًا ولا تُؤسر.","وحين يمتلئ اللوح يكون أحد الطرفين متصلًا لا محالة، فالسداسيات لا تتلامس عند زاوية فقط، فلا يمكن التسلل عبر خط الخصم. وفي 1979 بيّن عالم الرياضيات ديفيد غيل أن خاصية «لا تعادل» هذه تكافئ نتيجة رياضية شهيرة هي مبرهنة النقطة الثابتة لبراور."],"cap":["لوح هيكس 7 × 7. يفوز الأحمر بوصل الأعلى بالأسفل، والأزرق بوصل اليسار باليمين. وقد وصلت الحجارة الحمراء ذات الإطار الذهبي الأعلى بالأسفل"]},{"h":"الجسور والسلالم","p":["من أحب أدوات اللاعبين الأقوياء «الجسر»: إذا وضعت حجرًا لا بجوار سابقه مباشرة بل على بعد خلية، تشارك الحجران في خليتين خاليتين. فإن سدّ الخصم واحدة أخذت الأخرى، فهما عمليًا متصلان.","وقرب الحواف تُعرف أشكال ثابتة كثيرة، مثل «السلالم» من الحجارة التي تسير بمحاذاة الحافة حتى تبلغها. ولأن ميزة اللاعب الأول كبيرة جدًا تُستعمل عادة قاعدة المبادلة: بعد النقلة الأولى يجوز للاعب الثاني أن يأخذ ذلك الحجر لنفسه."],"cap":["«الجسر». يمكن وصل الحجرين الأحمرين عبر أي من الخليتين الخاليتين بينهما (الدائرتان المنقطتان). فإن أخذ الأزرق إحداهما أخذ الأحمر الأخرى"]},{"h":"لعبة الرياضيين","p":["أثبت ناش أن اللاعب الأول يفوز بحجة «سرقة الاستراتيجية»: لو كانت للثاني استراتيجية رابحة لأمكن للأول أن يستولي عليها، وهذا تناقض. إنه برهان غريب لا يُظهر أي نقلة رابحة.","وفي الخمسينيات بنى كلود شانون، أبو نظرية المعلومات، آلة تلعب الهيكس بدائرة كهربائية. وفي العقد الثاني من القرن الحادي والعشرين حلّت الحواسيب كل الألواح حتى 9 × 9، لكن اللوح الرسمي 11 × 11 ما زال بلا حل."],"cap":[]}],"tl":[["1942","هاين ينشر «بوليغون» في صحيفة دنماركية"],["1948–49","ناش في برينستون يبتكر اللعبة نفسها"],["1952","باركر براذرز تبيعها باسم «هيكس»"],["الخمسينيات","شانون يبني آلة كهربائية تلعب الهيكس"],["1957","غاردنر يقدّمها في عموده"],["1979","غيل يبيّن صلتها بمبرهنة النقطة الثابتة"],["العقد الثاني من القرن 21","حل الألواح حتى 9 × 9 بالحاسوب"]]},"foxgeese":{"title":"الثعلب والإوز وقطع الملك الفضية","lead":"ثعلب واحد وإوز كثير: التاريخ الطويل لـ«لعبة صيد» لا يتساوى فيها الطرفان أبدًا.","s":["في لعبة الثعلب والإوز يقفز ثعلب وحيد فوق الإوز ليأكله، بينما يحاول الإوز حصره حتى لا يستطيع الحركة. ولكل طرف قواعده، على لوحة صليبية من 33 نقطة تصل بينها خطوط.","ومن الخيوط المبكرة «هالاتافل» في «ملحمة غريتير» الآيسلندية المكتوبة نحو القرن الرابع عشر. ومعناها «لوحة الذيل»، والذيل على الأرجح ذيل الثعلب. وربما كانت فرعًا من ألعاب التافل الإسكندنافية.","وفي إنجلترا تسجّل حسابات الملك إدوارد الرابع في القرن الخامس عشر شراء «ثعلبين و26 كلب صيد من الفضة المذهّبة» — قطع لطقمين، كانت تُسمّى آنذاك على ما يبدو «الثعلب وكلاب الصيد».","ومع الإوزات الثلاث عشرة الأصلية كان الثعلب أقوى مما ينبغي، فانتشرت طرق لعب بإوز أكثر. ويُقال إن الملكة فيكتوريا كانت تحب هذه اللعبة في القرن التاسع عشر.","واللوحة الصليبية نفسها تُستعمل في لعبة «سوليتير الأوتاد» الفردية. وألعاب الصيد التي يطارد فيها نمر أو ذئب فريسته، مثل «باغ تشال» النيبالية، موجودة في أنحاء العالم. وفي الأطلس يمكنك لعب الثعلب والإوز وسوليتير الأوتاد معًا."],"quiz":[["ما معنى «هالا» في هالاتافل؟","الذيل","الثعلب","الملك","الثلج"],["ما القطع المذكورة في حسابات إدوارد الرابع؟","ثعالب وكلاب صيد من الفضة","إوز من الذهب","ملك من العاج","نرد خشبي"],["أي لعبة فردية تستعمل اللوحة الصليبية نفسها؟","سوليتير الأوتاد","سودوكو","سوليتير الورق","تانغرام"]],"kf":["ثعلب واحد ضد 13 إوزة (ثم 17) على لوح صليبي من 33 نقطة","يأسر الثعلب بالقفز، ويفوز الإوز إذا حاصره حتى يعجز عن الحركة","اللوح نفسه يُستعمل في «سوليتير الأوتاد»، وألعاب الصيد من هذا النوع موجودة في العالم كله"],"more":[{"h":"واحد ضد ثلاث عشرة","p":["يتحرك الثعلب خطوة على الخطوط، ويأسر بالقفز فوق إوزة مجاورة إذا كانت النقطة التي خلفها خالية، وقد يتابع القفز مرات متتالية كما في الداما. ولا يأسر الإوز، ولا يتراجع في كثير من النسخ.","يسعى الإوز إلى رصّ صفوفه بلا ثغرات وحصر الثعلب حتى لا تبقى له نقلة. ويُقال إن الثعلب يتفوق كثيرًا مع ثلاث عشرة إوزة، أما مع سبع عشرة إوزة لا تتراجع فاللعب الجيد يمنح الإوز الفوز."],"cap":["لوح الثعلب والإوز: 33 نقطة على شكل صليب تصل بينها خطوط. تقف ثلاث عشرة إوزة في الأعلى، ويستطيع الثعلب (البرتقالي) أكل الإوزة التي أمامه مباشرة (×) بالقفز إلى النقطة الخالية خلفها"]},{"h":"عائلة ألعاب الصيد","p":["قطع قليلة قوية تطارد قطعًا كثيرة ضعيفة: ألعاب الصيد هذه موجودة في كل مكان. ففي «باغ تشال» النيبالية تطارد أربعة نمور عشرين عنزة على لوح 5 × 5، وقد أظهر الحساب في 2004 أنها تنتهي بالتعادل باللعب المثالي.","و«أسالتو» التي راجت في ألمانيا القرن التاسع عشر تستعمل اللوح الصليبي نفسه: ضابطان ضد أربعة وعشرين جنديًا. وهنا يدافع الضابطان عن قلعة يحاول الجنود اقتحامها."],"cap":["ألعاب الصيد بالأرقام: الصيادون يسارًا (برتقالي) والطرائد يمينًا (أبيض). من الأعلى: الثعلب والإوز (1:13)، والنسخة بإوز أكثر (1:17)، و«باغ تشال» النيبالية (4:20)، و«أسالتو» (2:24)"]},{"h":"من قطع الملك إلى سوليتير الأوتاد","p":["تسجل حسابات إدوارد الرابع ملك إنجلترا (حكم 1461–83) شراء قطع من الفضة المذهّبة للعبة الثعلب وكلاب الصيد. فقد كانت أيضًا تسلية الملوك والنبلاء.","واللوح الصليبي نفسه ذو الثقوب الـ33 يُستعمل في «سوليتير الأوتاد» الذي يُلعب فرديًا. وفي نقش فرنسي من عام 1697 سيدة نبيلة تلعبه، وهو من أقدم ما سُجّل عن هذه اللعبة."],"cap":[]}],"tl":[["نحو القرن 14","ظهور «هالاتافل» في «ملحمة غريتير» الآيسلندية"],["أواخر القرن 15","إدوارد الرابع يشتري قطعًا فضية للثعلب وكلاب الصيد"],["1697","نقش فرنسي يصوّر سيدة تلعب سوليتير الأوتاد"],["القرن 19","يُروى أن الملكة فيكتوريا أحبت اللعبة"],["القرن 19","رواج «أسالتو» على اللوح نفسه في ألمانيا"],["2004","إظهار أن «باغ تشال» النيبالية تعادل باللعب المثالي"]]},"latrunculi":{"title":"لوح الجنود الرومان","lead":"لعبة شغف بها الرومان، تحمل اسم الجنود المرتزقة. لم يبقَ كتاب لقواعدها؛ لم يبقَ إلا أشعار وحكايات وألواح خرجت من الأرض.","s":["كانت «لودوس لاترونكولوروم» لعبة حرب لاثنين في روما القديمة. وكانت كلمة «لاترونكولي» تعني في الأصل الجنود المرتزقة أو اللصوص، وكانت القطع تمثّل الجنود.","كانت القطع تتحرك على لوح مخطط، وتُؤسر القطعة المحصورة بين قطعتين للعدو. وتصف قصيدة من القرن الأول، «مديح بيسو»، قطعًا تتقدم وتتراجع، وقطعة محاصرة لا تستطيع الحركة.","يروي الفيلسوف سينيكا قصة يوليوس كانوس الذي حكم عليه الإمبراطور كاليغولا بالموت. فحين جاءه قائد المئة ليأخذه كان يلعب اللاترونكولي، فعدّ القطع وقال لخصمه ألّا يدّعي بعد موته أنه فاز.","عُثر على ألواح في أنحاء الإمبراطورية كلها. والشبكات المحفورة على حجارة الحصون والمدن تتراوح بين نحو 8 × 8 و12 × 12. وفي قبر من القرن الأول في ستانواي بإنجلترا بقيت قطع زجاجية مرصوفة على لوحها.","لم يبقَ كتاب مفصّل للقواعد، والقواعد اليوم إعادة بناء من الباحثين. ويستند لاترونكولي الأطلس إلى واحدة منها."],"quiz":[["كيف تُؤسر القطعة في اللاترونكولي؟","بحصرها بين قطعتين","بالقفز فوقها","برمية نرد","بمحاصرة الملك"],["من كان يلعب اللاترونكولي حين جاؤوا ليقتادوه إلى الإعدام؟","يوليوس كانوس","قيصر","نيرون","شيشرون"],["ما الذي بقي على اللوح في قبر ستانواي؟","قطع زجاجية","عملات ذهبية","قطع شطرنج","أوراق لعب"]],"kf":["لعبة حرب لاثنين في روما القديمة، قطعها تمثّل الجنود","تُؤسر القطعة المحصورة بين قطعتين للعدو، وتُذكر أيضًا القطع العاجزة عن الحركة","لا كتاب قواعد: يُعاد بناؤها من الأشعار والحكايات والألواح المكتشفة"],"more":[{"h":"احصر وحاصر","p":["أغنى مصدر لإعادة البناء قصيدة «مديح بيسو» من القرن الأول. فهي تصف اللعبة كأنها ساحة قتال: قطعة تتقدم لتستدرج العدو، وأخرى تحمي ظهرها، ومن وقعت بين عدوين خسرت.","وتتحدث القصيدة أيضًا عن قطعة محاصرة عاجزة عن الحركة، لذا تضيف إعادات بناء كثيرة قاعدة للقطع المسدودة إلى جانب الأسر بالحصر. وفي ألعاب التافل الشمالية أسر مشابه جدًا."],"cap":["الأسر في اللاترونكولي (إعادة بناء). يسارًا: بالتقدم كما يُظهر السهم الأزرق تنحصر القطعة البيضاء بين سوداوين فتُؤسر (×). يمينًا: قطعة بيضاء مسدودة من الجهات الأربع لا تتحرك"]},{"h":"لوح بوجهين","p":["في قصيدة رافقت هدية يصف الشاعر مارتياليس (القرن الأول) لوحًا تتقدم القطع على أحد وجهيه برمي النرد، ويتقاتل على الآخر جنود بلونين: لعبة حظ ولعبة عقل على لوح واحد.","ويُظن أن وجه النرد هو لعبة السباق المسماة «الخطوط الاثني عشر»، سلف التابولا والطاولة. وبرج النرد (بيرغوس) في مقتنيات المتحف أداة أخرى استعملها الرومان."],"cap":["تصوّر للوح مارتياليس ذي الوجهين: على وجه سباق «الخطوط الاثني عشر» بالنرد، وعلى الآخر شبكة لعبة الجنود"]},{"h":"ألواح من باطن الأرض","p":["كان الجنود الرومان يحفرون الشبكات على حجارة حصونهم وأرضياتها ليلعبوا. وقد وُجدت ألواح محفورة قرب سور هادريان في بريطانيا، وفي ألمانيا وإسبانيا وشمال أفريقيا.","في قبر ستانواي (منتصف القرن الأول) تعفّن اللوح الخشبي، لكن القطع الزجاجية البيضاء والزرقاء بقيت في أماكنها كأن الدور لم ينتهِ. وربما كان صاحبها طبيبًا، إذ دُفنت معها أدوات طبية."],"cap":["برج نرد (بيرغوس). كان الرومان يرمون النرد عبر أبراج كهذه منعًا للغش"]}],"tl":[["القرن 1 ق.م","فارو يذكر اللاترونكولي"],["أواخر القرن 1 ق.م","أوفيد يشير إلى اللعبة في شعره الغزلي"],["القرن 1","«مديح بيسو» يصف اللعبة شعرًا"],["منتصف القرن 1","دفن لوح بقطعه المرصوفة في ستانواي"],["القرن 1","سينيكا يروي حكاية يوليوس كانوس"],["أواخر القرن 1","مارتياليس يكتب عن لوح بوجهين"],["1994","شيدلر ينشر إعادة بناء للقواعد"]]},"amazons":{"title":"اللعبة التي تحرق لوحها","lead":"وُلدت لعبة «الأمازونات» في الأرجنتين عام 1988، فجمعت حركة وزير الشطرنج إلى عدّ الأرض كما في الغو.","s":["لعبة الأمازونات لاثنين على لوح 10 × 10، ولكل طرف أربع «أمازونات». ابتكرها الأرجنتيني فالتر زامكاوسكاس عام 1988.","للنقلة جزآن: تتحرك الأمازونة أولًا كوزير الشطرنج في خط مستقيم أفقيًا أو عموديًا أو قطريًا، ثم تطلق من حيث وصلت سهمًا بالطريقة نفسها. والمربع الذي يقع فيه السهم لا يُعبر بعد ذلك أبدًا.","كل نقلة تملأ مربعًا آخر، ويخسر اللاعب الذي لم يعد يستطيع الحركة. ولا تعادل.","وقرب النهاية تقسم السهام اللوح إلى غرف منفصلة، فيفوز صاحب المربعات الخالية الخاصة الأكثر، ولذا يُقدَّر الوضع بعدّ الأرض كما في الغو.","للنقلة الأولى وحدها أكثر من 2000 احتمال، مما يجعلها صعبة حتى على الحواسيب. ويدرسها الرياضيون، وهي من مسابقات بطولات الحاسوب."],"quiz":[["في أي بلد وُلدت لعبة الأمازونات؟","الأرجنتين","البرازيل","إسبانيا","المكسيك"],["ماذا يحدث للمربع الذي يُطلق عليه سهم؟","لا يمكن لأحد عبوره بعد ذلك","يختفي في الدور التالي","يصير قطعة للخصم","يحتسب نقطة"],["من يخسر في لعبة الأمازونات؟","أول من يعجز عن الحركة","أول من يخسر قطعة","أول من يكوّن أرضًا","من ينفد وقته"]],"kf":["لعبة لاثنين على لوح 10 × 10، وُلدت في الأرجنتين عام 1988","تتحرك الأمازونة كالوزير ثم تطلق من موضعها سهمًا يحرق مربعًا","يخسر من لا يستطيع الحركة، وفي النهاية تُعدّ الأرض كما في الغو"],"more":[{"h":"تحرّك ثم ارمِ","p":["يمكن للأمازونة أن تتحرك أي عدد من المربعات ما دامت لا تتخطى قطعة أو سهمًا. ومن المربع الذي بلغته تطلق سهمًا بحركة الوزير أيضًا، حتى إلى المربع الذي غادرته للتو.","لا يؤسر شيء أبدًا. بل تغلق كل نقلة مربعًا من اللوح وتقطع طرق الخصم: فالهجوم والدفاع يحسمهما السهم نفسه."],"cap":["نقلة في لعبة الأمازونات. تتحرك الأمازونة البيضاء كالوزير (بالأزرق)، ثم تطلق من حيث وصلت سهمًا بالطريقة نفسها (بالأحمر). ومربع السهم مغلق إلى الأبد"]},{"h":"لوح ينقسم إلى غرف","p":["مع تقدم الدور تقسم السهام اللوح إلى غرف. فإذا لم يكن في غرفة إلا أمازونات لاعب واحد صارت مربعاتها الخالية له وحده، يستهلك منها واحدًا في كل نقلة.","وعندئذ يصير الدور عدًّا: من كانت مربعاته الصالحة أكثر استطاع الحركة أطول. وهذا يلائم نظرية الألعاب التوافقية، وقد درس إلوين بيرلكامب وغيره نهايات الأمازونات بالتفصيل."],"cap":["وضع ختامي (رسم توضيحي). جدران من المربعات المحترقة تقسم اللوح إلى أربع غرف: الخضراء لا يستعملها إلا الأبيض، والزرقاء إلا الأسود. ومن كانت مربعاته الخالية أكثر استطاع الحركة أطول"]},{"h":"وُلدت في مجلة وتتنافس فيها الحواسيب","p":["يُقال إن اللعبة نُشرت أول مرة في مجلة ألغاز أرجنتينية. قواعدها قصيرة، ويكفيها لوح شطرنج وبضع قطع، فانتشرت في العالم عبر الإنترنت.","مع أكثر من 2000 نقلة أولى ممكنة، تتطلب الافتتاحية إحساسًا باللوح كله كما في الغو. ومنذ العقد الأول من القرن الحادي والعشرين صارت من مسابقات بطولات الحاسوب، حيث تتبارى البرامج."],"cap":[]}],"tl":[["1988","فالتر زامكاوسكاس يبتكر لعبة الأمازونات"],["التسعينيات","انتشارها في العالم عبر الإنترنت"],["2000","بيرلكامب ينشر دراسات رياضية عن نهاياتها"],["العقد الأول من القرن 21","تصبح من مسابقات أولمبياد الحاسوب"]]},"loa":{"game":"خطوط الحركة (Lines of Action)","title":"قطع تتقدّم بقدر ما تعدّ","lead":"ظهرت لعبة «خطوط الحركة» عام 1969 في كتاب لسيد ساكسون. لا يفوز من يأسر أكثر، بل من يجمع كل قطعه في مجموعة واحدة.","s":["«خطوط الحركة» (LOA) لعبة لاثنين على لوح 8 × 8، لكل طرف اثنتا عشرة قطعة. ابتكرها كلود سوسي، وقدّمها عام 1969 جامع الألعاب سيد ساكسون في كتابه A Gamut of Games.","تتحرك القطعة في خط مستقيم، أفقيًا أو رأسيًا أو قُطريًا. والمسافة تساوي تمامًا عدد القطع — قطعك وقطع خصمك — على ذلك الخط. وكل نقلة تغيّر هذه الأعداد، فتتغير المسافات معها.","يجوز القفز فوق قطعك، أما قطع الخصم فلا يجوز أبدًا. وإذا توقفت على قطعة للخصم أسرتها.","الهدف أن تجمع كل قطعك في مجموعة واحدة تتلامس أفقيًا أو رأسيًا أو قُطريًا. والأسر يقلّل جيش الخصم، وقد يساعده ذلك على التجمّع — مفارقة طريفة.","القواعد قصيرة، لكن حساب النقلات القادمة صعب، ولذلك استُخدمت اللعبة طويلًا في أبحاث الذكاء الاصطناعي للألعاب. وفازت برامج من جامعة ماستريخت في هولندا ببطولات الحاسوب مرات كثيرة."],"quiz":[["ما الذي يحدد عدد المربعات التي تتحركها القطعة؟","عدد القطع على ذلك الخط","رمية النرد","عدد القطع المأسورة حتى الآن","ثلاثة مربعات دائمًا"],["كيف تفوز في «خطوط الحركة»؟","بجمع كل قطعك في مجموعة واحدة","بأسر كل قطع الخصم","بالوصول إلى الطرف المقابل من اللوح","بأسر ملك الخصم"],["من قدّم اللعبة في كتاب عام 1969؟","سيد ساكسون","مارتن غاردنر","إدموند هويل","هـ. ج. ر. موراي"]],"kf":["لعبة لاثنين على لوح 8 × 8، لكل منهما اثنتا عشرة قطعة؛ ابتكرها كلود سوسي وقُدّمت في كتاب سيد ساكسون عام 1969","تتحرك القطعة بعدد المربعات المساوي تمامًا لعدد القطع على خطها؛ تقفز فوق قطعها ولا تقفز فوق قطع الخصم أبدًا","لا يفوز من يأسر أكثر، بل من يجمع كل قطعه أولًا في مجموعة واحدة"],"more":[{"h":"عُدّ ثم تقدّم","p":["إذا كانت على الصف المارّ بقطعةٍ ما ثلاث قطع مثلًا، تقدّمت تلك القطعة على امتداده ثلاثة مربعات بالضبط، لا أكثر ولا أقل. ويجوز أن تمرّ فوق قطعها، لكن إن كانت بينها قطعة للخصم فلا يمكنها السير في ذلك الاتجاه.","كل قطعة تقع على أربعة خطوط — صف وعمود وقُطرين — ولكلٍّ منها عدده. فإذا تحركت قطعة تغيّرت أعداد عدة خطوط حولها، فتُخلط «المسافات» على اللوح من جديد مع كل نقلة. وهذا ما يجعل اللعبة عصيّة على التوقّع."],"cap":["إلى أين تذهب القطعة السوداء التي تنطلق منها الأسهم. في الصف 3 قطع فتتقدم 3 (القفز فوق قطعتها مسموح)؛ وفي العمود قطعتان فتتقدم 2 وتأسر قطعة بيضاء. وعلى القُطر 3 قطع أيضًا، لكن قطعة بيضاء تسدّ الطريق (×)"]},{"h":"المجموعة الواحدة تفوز","p":["تُعدّ القطع متصلة إذا تلامست أفقيًا أو رأسيًا أو قُطريًا. ومن بقيت له قطعة واحدة فهو «متصل» أيضًا، لذا قد يهدي الإفراطُ في الأسر النصرَ إلى الخصم.","أما إذا وصلت نقلة واحدة الطرفين معًا، فالحكم يختلف باختلاف الطبعة والبطولة: عدّته الطبعة الأولى من كتاب ساكسون تعادلًا، وعدّته طبعة لاحقة فوزًا لمن تحرّك، ومعظم البطولات اليوم تحتسبه تعادلًا. وفي نسخة هذا الأطلس يفوز من تحرّك."],"cap":["وضع فائز. القطع البيضاء (ذات الحافة الذهبية) يلمس بعضها بعضًا، بما في ذلك القُطري، وتشكّل مجموعة واحدة. أما السوداء فما زالت مقسّمة إلى ثلاث (خط متقطع)"]},{"h":"لعبة تنافست عليها الحواسيب","p":["بلوحها الصغير وقواعدها القصيرة وعمقها، صارت اللعبة ميدان اختبار للذكاء الاصطناعي في الألعاب. وفاز برنامج MIA الذي كتبه مارك فينانتس في جامعة ماستريخت بأولمبياد الحاسوب في 2003 و2004 و2006 و2009، وجُمع عمله في أطروحته للدكتوراه عام 2004، Informed Search in Complex Games.","وفي 2008 حلّ فينانتس اللعبة على لوح مصغّر 6 × 6، وبيّن أن اللاعب الأول (الأسود) يفوز إذا لعب الطرفان على أكمل وجه. ويُعتقد أن اللعبة الكاملة 8 × 8 لم تُحلّ بعد. ويلتقي اللاعبون من البشر أيضًا في بطولة عالم تُقام كل عام ضمن أولمبياد الرياضات الذهنية."],"cap":[]}],"tl":[["نحو 1960","يُقال إن كلود سوسي ابتكر اللعبة"],["1969","تقديمها في كتاب A Gamut of Games لسيد ساكسون"],["2003","برنامج MIA لفينانتس يفوز بأولمبياد الحاسوب (ثم في 2004 و2006 و2009)"],["2004","أطروحة فينانتس للدكتوراه Informed Search in Complex Games"],["2008","حلّ اللعبة على لوح 6 × 6: الفوز للاعب الأول"]]},"konane":{"title":"لعبة الحمم السوداء والمرجان الأبيض","lead":"لعبة «كونانيه» التي لعبها أهل هاواي دُوّنت في رواية رحلة كوك، وفي القرن العشرين فكّكها علماء الرياضيات بنظرية الألعاب التوافقية.","s":["«كونانيه» لعبة لاثنين من سكان هاواي الأصليين. تملأ الحجارة السوداء والبيضاء اللوح بالتناوب دون فراغ، ويأسر اللاعبون حجارة الخصم بالقفز فوقها.","كانت الحجارة السوداء قديمًا من الحمم، والبيضاء من قطع المرجان. أما اللوح المسمّى «بابامو» فكان حجرًا مسطحًا كبيرًا نُقرت في سطحه حفر صغيرة. ويُقال إن اللعبة تَرِد حتى في «كوموليبو»، نشيد الخلق الهاوايي.","يرفع الأسود أولًا حجرًا من حجارته، ثم يرفع الأبيض حجرًا مجاورًا له. والحفرتان الناتجتان هما نقطة بداية القفز.","كل نقلة أسر. يقفز الحجر أفقيًا أو رأسيًا فوق حجر للخصم ملاصق له، ويحطّ في المربع الفارغ خلفه. وما دام يسير في خط مستقيم، يجوز له مواصلة القفز.","يخسر من لم تبقَ له نقلة أسر، ولا تعادل في اللعبة. وقد جذب هذا التصميم البسيط لاحقًا اهتمام علماء الرياضيات."],"quiz":[["ممّ كانت حجارة «كونانيه» البيضاء القديمة؟","من المرجان","من العاج","من الرخام الأبيض","من عظام الحيوانات"],["من يخسر في «كونانيه»؟","من لم تبقَ له نقلة أسر","من أُسرت كل حجارته","أول من يبلغ حافة اللوح","من بقي له حجر واحد"],["عند القفز المتتالي، ما الممنوع؟","تغيير الاتجاه في الطريق","أسر أكثر من حجر في الدور","التوقف في المنتصف","الحطّ بجوار أحد حجارتك"]],"kf":["لعبة لاثنين من سكان هاواي الأصليين، تبدأ بحجارة سوداء (حمم) وبيضاء (مرجان) متناوبة تملأ اللوح كله","كل نقلة قفزة أفقية أو رأسية فوق حجر للخصم تأسره؛ وفي خط مستقيم يمكن القفز من جديد","يخسر من لا يجد أسرًا؛ ودرسها علماء الرياضيات بنظرية الألعاب التوافقية"],"more":[{"h":"اقفز وأسِر","p":["القفز أفقي أو رأسي فقط، ولا يكون قُطريًا أبدًا. فإذا كان المربع خلف حجر الخصم الملاصق فارغًا، قفز الحجر وحطّ فيه، ورُفع الحجر المقفوز عنه من اللوح.","وإن استطاع القفز مرة أخرى من حيث حطّ، جاز له المواصلة في الاتجاه نفسه. ولا يجوز تغيير الاتجاه في الطريق، ويجوز التوقف متى شاء. ولا يتحرك في الدور إلا حجر واحد."],"cap":["حجر أبيض يقفز مرتين إلى اليمين في دور واحد ويأسر حجرين أسودين (الأزرق 1 و2). ولا يجوز له أن ينعطف ويقفز إلى الأسفل من حيث حطّ (×)"]},{"h":"الحفرتان الأوليان","p":["على لوح ممتلئ بالحجارة لا يستطيع أحد القفز. لذلك يرفع الأسود، وهو البادئ، حجرًا من حجارته من المربعات الأربعة في الوسط أو من زاوية. ثم يرفع الأبيض حجرًا من حجارته يلاصق تلك الحفرة أفقيًا أو رأسيًا.","والحفرتان المتجاورتان هما أول موضعين للحطّ، وموضع فتحهما يرسم مسار اللعبة كلها."],"cap":["طريقتا البدء: يرفع الأسود حجرًا من حجارته من المربعات الأربعة في الوسط (يسارًا) أو من زاوية (يمينًا) (1)، ثم يرفع الأبيض حجرًا مجاورًا (2)"]},{"h":"ألواح حجرية و238 مربعًا","p":["تصف رواية رحلة جيمس كوك الثالثة (المجلد الثالث، المنشور عام 1784) لعبة حجارة شوهدت في هاواي بأنها «تشبه كثيرًا لعبة الداما عندنا»، لكنها أكثر تعقيدًا. وكاتبها الضابط جيمس كينغ، ويذكر أن طول اللوح نحو قدمين، وفيه 238 مربعًا، أربعة عشر في كل صف.","لم يكن للّوح مقاس ثابت: فهناك ألواح معروفة بمقاسات 6 × 7 و9 × 13 و13 × 20 وغيرها. واليوم تُلعب غالبًا على لوح مربع زوجي الأضلاع، ويتيح هذا الأطلس 6 × 6 و8 × 8 و10 × 10. وما زالت ألواح «بابامو» المنحوتة في الصخر قائمة في متنزه بوأوهونوا أو هوناوناو التاريخي الوطني في جزيرة هاواي."],"cap":["مقارنة مقاسات الألواح: لوح 14 × 17 (238 مربعًا) الوارد في رواية رحلة كوك، وألواح 10 × 10 و8 × 8 و6 × 6 التي يمكن اللعب عليها في هذا الأطلس"]},{"h":"لعبة اكتشفها علماء الرياضيات","p":["في «كونانيه» يخسر من لا يستطيع الحركة، وفي آخرها ينقسم اللوح إلى أجزاء مستقلة؛ وهذا يلائم تمامًا نظرية الألعاب التوافقية التي وضعها إلوين بيرلكامب وزملاؤه. كتب مايكل إرنست مع بيرلكامب مقالًا قصيرًا عن اللعبة عام 1993، ثم حسب في بحث عام 1995 قيم مواضع كثيرة.","وتلت ذلك أبحاث أخرى: درست أليس تشان وأليس تساي «كونانيه» ذات الصف الواحد (2002)، وبيّن بوب هيرن أن تحديد الفائز يزداد صعوبة بالغة كلما كبر اللوح (PSPACE-كاملة). وهكذا صارت لعبة قفز الحجارة موضوعًا في نظرية الحوسبة."],"cap":[]}],"tl":[["1778","سفن كوك تبلغ هاواي"],["1784","نشر رواية رحلة كوك الثالثة، وفيها وصف كينغ للعبة الحجارة"],["1993","إرنست وبيرلكامب يكتبان مقالًا قصيرًا عن «كونانيه»"],["1995","بحث إرنست «Playing Konane Mathematically»"],["2002","تشان وتساي يلخصان نتائجهما عن «كونانيه» ذات الصف الواحد"]]},"peg":{"title":"لغز القفز الذي وُلد في بلاط ملكي","lead":"كانت لعبة «سوليتير الأوتاد» تُلعب في أواخر القرن السابع عشر في بلاط لويس الرابع عشر بفرنسا. لغز بسيط تُنقص فيه الأوتاد واحدًا تلو الآخر، ولا يزال يفتن علماء الرياضيات منذ ذلك الحين.","s":["سوليتير الأوتاد لغز يلعبه شخص واحد. تملأ الأوتادُ ثقوب اللوح، ويبقى ثقب واحد فارغًا.","يقفز الوتد أفقيًا أو رأسيًا فوق وتد مجاور إلى الثقب الفارغ خلفه، ويُرفع الوتد المقفوز عنه من اللوح.","الهدف أن تواصل القفز حتى يبقى وتد واحد. وإبقاؤه في المركز تمامًا هو النهاية المثالية.","تأتي أولى السجلات المؤكدة من فرنسا في أواخر القرن السابع عشر، من بلاط لويس الرابع عشر. ففي 1697 نشرت مجلة «ميركور غالان» اللوح وقواعده، وتُظهر نقشة سيدةً نبيلة وبجانبها لوح.","يبدو سهلًا لكنه صعب. اهتم به الرياضي لايبنتس، وفي القرن العشرين شرح علماء الرياضيات، بتلوين الثقوب، لماذا لا حلّ لبعض المسائل."],"quiz":[["ماذا يحدث للوتد الذي يُقفز فوقه؟","يُرفع من اللوح","يصبح للخصم","ينزلق إلى الثقب المجاور","يعود في الدور التالي"],["كم ثقبًا في اللوح الإنجليزي؟","33","37","45","64"],["من أين تأتي أولى السجلات المؤكدة للعبة؟","من بلاط لويس الرابع عشر في أواخر القرن السابع عشر","من حمّامات روما القديمة","من مدرسة معبد في اليابان في عصر إيدو","من حانة في أمريكا القرن التاسع عشر"]],"kf":["لغز قفز لشخص واحد: تقفز فوق الأوتاد لترفعها، وتفوز إذا بقي وتد واحد","تبدأ السجلات المؤكدة نحو 1697 في بلاط لويس الرابع عشر؛ وللألواح التقليدية 33 ثقبًا (الإنجليزي) و37 (الأوروبي)","تلوين الثقوب بثلاثة ألوان يكشف مسبقًا أيّ المسائل لا حلّ لها"],"more":[{"h":"اقفز وارفع","p":["القفز أفقي أو رأسي فقط، ولا يكون قُطريًا أبدًا (إلا في الألواح ذات الخطوط القُطرية كالمثلث). وكل قفزة تُنقص وتدًا، فإذا بدأت بـ32 وتدًا احتجت إلى 31 قفزة حتى يبقى واحد.","يجوز للوتد نفسه أن يقفز مرات متتالية. وإذا عُدّت هذه السلسلة نقلة واحدة، حُلّت مسألة «من المركز إلى المركز» على اللوح الإنجليزي في 18 نقلة. وجد إرنست بيرغولت هذا الحل عام 1912، وأثبت جون بيزلي عام 1964 أنه لا يمكن بأقل من ذلك."],"cap":["النقلة الأولى على اللوح الإنجليزي. والمركز فارغ، يقفز الوتد العلوي فوق الذي تحته إلى المركز (الأزرق)، ويُرفع الوتد المقفوز عنه (×)"]},{"h":"من تسلية البلاط","p":["يرجع التاريخ المؤكد للعبة إلى بلاط لويس الرابع عشر نحو 1697. ففي أغسطس من ذلك العام وصفت «ميركور غالان» اللوح والقواعد وبعض المسائل، وصوّر النقّاش كلود أوغست بيري أميرة سوبيز وبجانبها لوح.","وتشتهر أيضًا قصة نبيل سُجن في الباستيل فاخترع اللغز ليقطع الوقت، لكنها أسطورة لا يمكن التحقق منها. ويُقال إن لوح الـ37 ثقبًا المستخدم في فرنسا يعود أيضًا إلى القرن السابع عشر، أما لوح الـ33 ثقبًا المقصوص الزوايا فيُسمّى اللوح الإنجليزي."],"cap":["اللوحان التقليديان: الإنجليزي بـ33 ثقبًا (يسارًا) والأوروبي بـ37 (يمينًا). الثقب الفارغ هو ثقب البداية المعتاد لكل منهما"]},{"h":"ما تكشفه ثلاثة ألوان","p":["لنلوّن الثقوب بثلاثة ألوان بحيث تمتد الألوان على الأقطار. عندئذ تكون أي ثلاثة ثقوب متتالية، أفقيًا أو رأسيًا، بثلاثة ألوان مختلفة دائمًا. والقفزة تأخذ وتدًا من لونين وتضيف وتدًا إلى الثالث، فتتبدّل زوجية أعداد الألوان الثلاثة معًا.","على اللوح الأوروبي والمركز فارغ، لكل لون 12 وتدًا، وكلها زوجية. وكل قفزة لا تفعل إلا التبديل بين «كلها زوجية» و«كلها فردية»، فلا يمكن أبدًا بلوغ وضع الوتد الأخير — لون فيه 1 ولونان فيهما 0. فعلى هذا اللوح لا حلّ للمسألة التي تبدأ من المركز. والفحص نفسه على اللوح الإنجليزي يحصر الثقوب التي يمكن أن ينتهي فيها الوتد الأخير، عند البدء من المركز، في خمسة فقط."],"cap":["اللوح الأوروبي ذو الـ37 ثقبًا ملوّنًا بثلاثة ألوان على امتداد الأقطار. والمركز فارغ، لكل لون 12 وتدًا"]},{"h":"لعبة لعلماء الرياضيات","p":["يُروى أن لايبنتس كتب في ملاحظة عام 1710 أنه يحب أن يلعبها بالعكس، أي بملء الثقوب التي قُفز فوقها. وما زال التفكير من النهاية إلى البداية طريقة أساسية لحلها.","حلّل كتاب «Winning Ways» (1982) لبيرلكامب وكونواي وغاي اللغز بالتفصيل، وقدّم «دوال الباغودا»: إذا أعطيت كل ثقب قيمة بحيث لا تزيد أي قفزة المجموع، أمكنك إثبات استحالة بعض الأهداف. ويُقال إن بحثًا حاسوبيًا فحص عام 1999 جميع الأوضاع."],"cap":[]}],"tl":[["1697","تُلعب في بلاط لويس الرابع عشر؛ و«ميركور غالان» عدد أغسطس تنشر اللوح والقواعد"],["1710","يُقال إن لايبنتس كتب عن لعبها بالعكس"],["1912","بيرغولت يجد حلًا من 18 نقلة على اللوح الإنجليزي"],["1964","بيزلي يثبت أنه لا حل بأقل من 18 نقلة"],["1982","«Winning Ways» يعرض تحليله، ومنه دوال الباغودا"]]},"fanorona":{"title":"الأسر بالاقتراب والأسر بالابتعاد","lead":"«فانورونا» هي اللعبة الوطنية في مدغشقر. تقول الأسطورة إنها حسمت عرشًا، وفي القرن الحادي والعشرين أثبتت الحواسيب أنها تنتهي بالتعادل إذا لعب الطرفان على أكمل وجه.","s":["«فانورونا» لعبة لاثنين واسعة الانتشار في مدغشقر. تُلعب على لوح 9 × 5 مخطوط بخطوط أفقية ورأسية وقُطرية، ولكل طرف 22 قطعة.","يبدو اللوح كلوحين من «القِرْقة» — وهي لعبة من العالم العربي وأوروبا — موضوعين جنبًا إلى جنب. ويُعتقد أن القِرْقة وصلت إلى الجزيرة وتحوّلت هناك إلى لعبة قائمة بذاتها.","أبرز ما يميزها طريقة الأسر: فالتحرك نحو قطعة الخصم («الاقتراب») أو بعيدًا عنها («الابتعاد») يأسر صف قطع الخصم كله على ذلك الخط.","الأسر إلزامي، والقطعة التي أسرت يجوز لها أن تغيّر اتجاهها وتواصل الأسر. ونقلة واحدة قد تقلب اللوح رأسًا على عقب، وهذه متعة فانورونا.","أحبّها الناس قرونًا، حتى إن لها أسطورة عن أمير خسر العرش لأنه لم يستطع ترك مباراة. وفي 2007 أثبت باحثون هولنديون بالحاسوب أن النتيجة تعادل إذا لعب الطرفان أفضل لعب."],"quiz":[["ما مقاس لوح فانورونا؟","9 × 5","8 × 8","7 × 7","6 × 6"],["ما طريقتا الأسر في فانورونا؟","الاقتراب والابتعاد","القفز والحصر","التطويق والدفع","النرد والقرعة"],["ماذا أثبتت الحواسيب عند أفضل لعب؟","التعادل","فوز اللاعب الأول","فوز اللاعب الثاني","لا شيء معروف بعد"]],"kf":["لعبة لاثنين من مدغشقر: 22 قطعة لكل طرف على لوح 9 × 5، والمركز وحده فارغ في البداية","الاقتراب من قطعة الخصم أو الابتعاد عنها يأسر الصف كله على ذلك الخط","في 2007 أثبتت الحواسيب أن أفضل لعب ينتهي بالتعادل"],"more":[{"h":"الاقتراب والابتعاد","p":["في الاقتراب، إذا كانت بعد نقطة الوصول مباشرة قطعة للخصم، أُسرت هي وكل قطع الخصم المصطفة خلفها بلا فراغ. والابتعاد عكسه: تُؤسر قطعة الخصم التي كانت خلف نقطة الانطلاق مباشرة والمصطفة خلفها.","ولأن خطوة واحدة قد تزيل عدة قطع معًا، تتناقص الجيوش بسرعة منذ البداية. وإذا أتاحت نقلة الاقتراب والابتعاد معًا، اختار اللاعب أحدهما."],"cap":["طريقتا الأسر. في الأعلى: يتقدم الأبيض خطوة إلى اليمين مقتربًا من قطعة سوداء فيأسر السود الثلاث المصطفة بعدها (اقتراب). في الأسفل: يتقدم الأبيض إلى اليمين مبتعدًا عن قطعة سوداء فيأسر السوداوين خلفه (ابتعاد)"]},{"h":"لوحا قِرْقة جنبًا إلى جنب","p":["في اللوح 5 × 9 = 45 نقطة؛ وإلى جانب الخطوط الأفقية والرأسية تمر الأقطار بنقطة وتترك أخرى. وتتحرك القطع خطوة واحدة على خط إلى نقطة مجاورة. وفي البداية لا يكون فارغًا إلا المركز، فتكون النقلة الأولى أسرًا دائمًا.","اللوح لوحا قِرْقة 5 × 5 موصولان. والقِرْقة لعبة قديمة ورد اسمها في كتاب عربي من القرن العاشر، ويُعتقد أن فانورونا نشأت منها. ولا يُعرف متى ولا كيف وصلت إلى الجزيرة؛ وتذكر بعض الكتب القرن السابع عشر."],"cap":["وضع البداية: 22 قطعة سوداء و22 بيضاء على نقاط 9 × 5، والنقطة الوسطى وحدها فارغة. المربعان المتقطعان يحددان لوحَي قِرْقة 5 × 5"]},{"h":"سلاسل الأسر","p":["يجوز للقطعة التي أسرت أن تأسر من جديد، لكن يجب أن تكون كل خطوة في اتجاه مختلف، ولا يجوز الرجوع إلى نقطة سبق المرور بها. والاستمرار من عدمه متروك للاعب.","إذا نجحت سلسلة كهذه، فقد تذهب نقلة واحدة بنحو نصف قطع الخصم. أما إذا انتهت في موضع سيئ، فسرعان ما تُؤسر القطعة ردًّا."],"cap":["سلسلة أسر: الأبيض (1) يقترب إلى اليمين فيأسر اثنتين، (2) يبتعد إلى الأعلى فيأسر اثنتين، (3) يقترب إلى اليسار فيأسر اثنتين. وبعد (1) لا يجوز له مواصلة السير إلى اليمين (×)"]},{"h":"عرش وحواسيب","p":["تقول الأسطورة إن رالامبو، ملك إيميرينا نحو القرن السادس عشر، تظاهر بالمرض ليرث العرش أول ابن يعود. فلم يستطع الابن الأكبر أندريانتومبوكويندريندرا ترك وضع صعب في فانورونا، وصار الأصغر أندريانجاكا ملكًا. وتروي قصة أخرى أن جانب الملكة اعتمد على مباراة طقسية في فانورونا أثناء الغزو الفرنسي عام 1895؛ ولا يمكن التحقق من أيٍّ منهما.","وفي 2007 حسب مارتن سخاد وزملاؤه في جامعة ماستريخت بهولندا كل الأوضاع التي فيها سبع قطع أو أقل، وأثبتوا ببحث «أعداد الإثبات» أن وضع البداية تعادل (نُشر البحث عام 2008). واستغرق الحساب أكثر من أسبوع على جهاز واحد."],"cap":[]}],"tl":[["نحو القرن 16","أسطورة خلافة الملك رالامبو وفانورونا"],["نحو القرن 17","رأي في وقت نشوء فانورونا من القِرْقة"],["1895","أسطورة مباراة فانورونا طقسية أثناء الغزو الفرنسي"],["2007","سخاد وزملاؤه يثبتون بالحاسوب أنها تعادل"],["2008","بحث «Best Play in Fanorona Leads to Draw»"]]},"janggi":{"title":"لوح بلا نهر ومدفع لا يقفز إلا مرة","lead":"«جانغي»، المحبوبة في كوريا، تستخدم لوح 9 × 10 نفسه الذي تستخدمه الشيانغ تشي الصينية، لكنها ألغت النهر وغيّرت حركة القطع كثيرًا.","s":["جانغي لعبة شطرنج لاثنين تُلعب في كوريا منذ زمن بعيد. ويُعتقد أنها جاءت من الشيانغ تشي الصينية، وتوضع قطعها على نقاط شبكة من 9 × 10 خطوط.","بخلاف الشيانغ تشي، لا «نهر» في وسط اللوح، فتستطيع الفيلة والجنود الذهاب إلى أي مكان. ويبدأ القائد (الملك) في وسط «قصره» ولا يغادره أبدًا.","الطرفان هما تشو (أزرق أو أخضر) وهان (أحمر). القطع ثُمانية الأضلاع، وكلما كانت القطعة أقوى كانت أكبر. ويبدأ تشو.","قبل اللعب يختار كل طرف واحدة من أربع طرق لترتيب الخيول والفيلة. يرتّب هان أولًا ويقرّر تشو بعد أن يراه، فتبدأ المناورة قبل النقلة الأولى.","إلى جانب الكش مات، يمكن حسم المباراة بالنقاط. يبدأ تشو، البادئ، بـ72 نقطة، ويحصل هان على «دوم» قدره 1.5 نقطة فيبدأ بـ73.5. وكل قطعة تُفقد تُنقص النقاط."],"quiz":[["ما الذي لا يوجد في لوح جانغي؟","نهر في الوسط","القصور","أقطار القصور","90 نقطة"],["ما الذي يجب على المدفع فعله دائمًا ليتحرك؟","أن يقفز فوق قطعة واحدة بالضبط","أن يقف بجوار قطعة للخصم","أن يكون داخل قصر","ألا يكون في كش"],["عند حساب النقاط، كم «دوم» يحصل عليه هان، اللاعب الثاني؟","1.5","0.5","3","6.5"]],"kf":["شطرنج كوريا المولود من الشيانغ تشي: لوح 9 × 10 لكن بلا نهر","الفيل يتحرك خطوة مستقيمة واثنتين قُطريتين؛ والمدفع يتحرك ويأسر بالقفز فوق قطعة واحدة بالضبط","يختار كل طرف واحدًا من أربعة ترتيبات للخيول والفيلة؛ وعند حساب النقاط يحصل هان على دوم 1.5"],"more":[{"h":"لوح بلا نهر وأربعة ترتيبات","p":["في لوح جانغي النقاط نفسها 9 × 10 كما في الشيانغ تشي، لكن بلا نهر في الوسط. وفي كل قصر أقطار على شكل X، ويتحرك القائد والحارسان داخله خطوة خطوة، وعلى الأقطار أيضًا. ويبدأ القائد في وسط قصره تمامًا.","الترتيبات أربعة، تنشأ من تبديل مواضع الخيول والفيلة. يرتّب هان أولًا، ويختار تشو بعد أن يراه. ووضع الفيلة في الداخل أو الخارج يغيّر طرق الهجوم في الافتتاح."],"cap":["لوح جانغي ووضع البداية. لا نهر، وفي القصرين أعلى وأسفل أقطار. الحلقات المتقطعة تُظهر مواضع يمكن فيها تبديل الخيول والفيلة؛ وقد اختار هان (أعلى) وتشو (أسفل) ترتيبين مختلفين"]},{"h":"الحصان والفيل والنقاط المسدودة","p":["يتقدم الحصان أولًا نقطة مستقيمة، ثم نقطة قُطرية إلى الخارج. ويذهب الفيل أبعد: نقطة مستقيمة ثم نقطتان قُطريتان. وفي الحالتين تسدّ القطعة الواقفة على نقطة في الطريق ذلك الاتجاه.","فيل الشيانغ تشي لا يعبر النهر ولا يتحرك إلا نقطتين قُطريتين، أما فيل جانغي فطويل الساقين يجوب اللوح كله. وفي المقابل يسهل سدّ طريقه."],"cap":["الحصان (يسارًا) خطوة مستقيمة ثم قُطرية، والفيل (يمينًا) خطوة مستقيمة ثم اثنتان قُطريتان. النقاط الزرقاء ما يمكن بلوغه. وقطعة على نقطة في الطريق تسدّ ذلك الاتجاه (×)"]},{"h":"المدفع الذي لا يقفز إلا مرة","p":["يجب على المدفع أن يقفز فوق قطعة وسيطة واحدة بالضبط، سواء ليتحرك أو ليأسر. وإذا لم يكن بينهما شيء لم يتحرك، ولذلك تبقى المدافع ساكنة في وضع البداية.","لا يجوز أن تكون القطعة المقفوز فوقها ولا المأسورة مدفعًا، فيبقى المدفعان يتبادلان النظرات فقط. ومقارنة بمدفع الشيانغ تشي الذي يتحرك بحرية حين لا يأسر، فهو قطعة أكثر تطلّبًا بكثير."],"cap":["المدفع. أعلى: يقفز فوق جندي واحد بالضبط إلى نقطة بعده، أو يأسر العربة (الأزرق). في الوسط: لا يقفز إذا كانت القطعة الوسيطة مدفعًا. أسفل: المدفع لا يأسر مدفعًا (×)"]},{"h":"قائدان متقابلان والنقاط","p":["حين يتقابل القائدان على خط لا شيء بينهما، يُسمّى ذلك «بيكجانغ» (빅장). وبحسب إحدى القواعد، إذا لم يكسر الطرف المواجَه ذلك انتهت المباراة بالتعادل. وتسمح القواعد التقليدية أيضًا بتمرير الدور إذا لم يكن اللاعب في كش.","القيم: العربة 13، المدفع 7، الحصان 5، الفيل 3، الحارس 3، الجندي 2. لتشو 72 نقطة، ولهان 73.5 مع الدوم. وبسبب نصف النقطة لا يحدث تعادل في النقاط أبدًا. وفي جانغي هذا الأطلس تحسم هذه النقاط النتيجة إذا تكرر وضع ثلاث مرات أو بعد 200 نقلة."],"cap":[]}],"tl":[["عصر غوريو","يرى رأيٌ أنها كانت تُلعب آنذاك (زمن وصولها موضع خلاف)"],["القرن 18","يُقال إن نسخة بلوح أكبر، «غوانغسانغهي»، مسجّلة"],["1895","كتاب ستيوارت كولين «Korean Games» ينشر رسمًا لرجال يلعبون جانغي"],["2009","يُقال إن أول بطولة دولية أُقيمت في هاربين بالصين"]]}};
